import type {Point} from "./text.tsx";

// every image in src/images/insights, looked up by file name
const images = import.meta.glob("../images/insights/*", {eager:true, import:"default"}) as Record<string, string>
const pic = (name: string) => images[`../images/insights/${name}`]

// Insights page filters
export const topics =["Industry Trends and Analysis","Product Management","Growth"]
export const contentTypes =["Article","Podcast","Report","Video","Webinar"]

// an article is paragraphs with these blocks in between, text can use **bold**, *italics* and [links](https://...)
//   heading - sub headings come out smaller
//   points  - a bullet list, numbered when ordered is set
//   image, video - video is a YouTube embed link
export type InsightBlock = string | {heading:string, sub?:boolean} | {points:Point[], ordered?:boolean}
    | {image:string, alt?:string, caption?:string} | {video:string, caption?:string} | {quote:string}

// shared by the Insights page (/insights), each article (/insights/:slug) and the cards on Home, newest first
export type Insight = {slug:string, title:string, topic:string, type:string, date:string, authors:string[], cover:string,
    summary:string, article:InsightBlock[]}

export const insights: Insight[] =[
    {slug:"your-product-has-a-back-door-and-you-probably-left-it-open", title:"Your Product Has a Back Door, and You Probably Left It Open.",
        topic:"Product Management", type:"Article", date:"May 12, 2026",
        authors:["Kenechi Ani (Senior Associate)", "Blessing Anyanwu (Operations Analyst)"], cover:pic("your-product-has-a-back-door-and-you-probably-left-it-open-1.jpg"),
        summary:"Glovo's fake restaurant scandal wasn't a fraud failure it was a product decision that prioritised speed over verification, and your team is probably making this kind of tradeoff without realising it.",
        article:[
            "Somewhere in Lagos in late 2025, a food vendor named Corporate Ewa, a brand customers loved and trusted, decided to order food from her own restaurant. Not to eat but to investigate.",
            "She had been getting complaints for months. Food that tasted wrong. Packaging was off. Quality that had dropped. What is shocking is that Corporate Ewa had never registered on Glovo. She had never listed a single item. Yet Corporate Ewa was fully live, with her menu and photos from her Instagram page. She decided to place an order.",
            "When the Glovo delivery rider arrived, he told her the food had been picked up from somewhere near Ojuelegba. No kitchen name. Just a pickup point used for multiple alias restaurant brands on the app. She reported it. Glovo told her the listing was legitimate. In October, she sent a Pre-Action letter from her Lawyer to Glovo. The listing stayed up. She went public on X in December and then everyone had a story. [One customer, Adenike Ruth](https://businessday.ng/news/article/impostor-meals-allegations-spark-food-safety-concerns-on-glovo/), said she took two days off work after a meal she thought came from Corporate Ewa left her nearly hospitalized.",
            "Techpoint Africa decided to run their own experiment. They impersonated a restaurant on both Glovo and Chowdeck using a forged CAC document, fake tax ID, stolen photos and a wrong address. Within 48 hours, they were live and making sales. The KYC wasn’t properly verified.",
            "Even though Chowdeck flagged the fake CAC document, the registration still went through with 100k withdrawal limit cap on the unverified vendor account.",
            "**This Is Not a Fraud Story. It Is a Product Story.**",
            "Glovo’s and Chowdeck’s onboarding worked exactly as designed; optimized for speed, built to get vendors live as fast as possible. However, a key question that every product team should be asking before they ship is:",
            "*What can go wrong? Not in terms of bugs or failed processes but what if the pertinent risks of our designed processes are working as intended.*",
            "When you build a marketplace, you are not just a technology company. You are a trust infrastructure. Your product is not the app it is the promise that the food a customer orders will come from the brand they recognize, cooked in that brand's kitchen. The moment you cannot guarantee that, the product’s ability to fulfill its core objective comes into question.",
            "**The Pattern Hiding in Plain Sight**",
            "This is not a Glovo problem. This is not a Chowdeck problem.",
            "This is a product governance problem and it shows up across African tech in different costumes:",
            {points:[
                "The fintech that onboards users in 60 seconds but takes 14 days to resolve a dispute.",
            ]},
            {points:[
                "The ecommerce platform that lists any seller instantly but has no counterfeit policy until a scandal hits.",
            ]},
            {points:[
                "The ride-hailing app that activates drivers without verifying their license until a passenger is harmed.",
            ]},
            "These symptoms point to the very familiar cycle of startups raising or eyeing VC funding and the focus becomes *GROWTH AS THE NORTH STAR. Product governance becomes an afterthought***.** Product teams find themselves making tradeoffs that eventually erode the intrinsic value that the product was meant to deliver.",
            "And the tradeoff that consistently gets made is verification because building fast in an emerging market is genuinely hard, regulatory data is thin, and competition for attention is brutal. That tradeoff is getting expensive.",
            "**Four Questions Your Product Team Is Probably Not Asking**",
            {image:pic("your-product-has-a-back-door-and-you-probably-left-it-open-2.jpg")},
            "**1. What can go wrong if this works exactly as designed?** Not if something breaks, if it works perfectly. This is a product design question, not a security question. It belongs in your discovery process, not your post-mortem.",
            "**2. Who actually bears the risk when something goes wrong?** In most Nigerian platform businesses, the answer is: not the platform. The vendor loses its reputation. The customer loses money, or worse their health. The platform loses a news cycle and issues a statement. If the organization is constantly catching up instead of staying ahead, that is not governance. It is a liability waiting to mature.",
            "**3. What costs more: building trust or repairing distrust?** A proper vendor verification system costs a fraction of one scandal, one lawsuit, one customer who ordered food and received something dangerous. The Corporate Ewa and Techpoint experiment does not require advanced technology to prevent it. It requires a decision. The CAC register and the NRS TIN portal are both publicly accessible with no special access required. Liveness and geolocation checks also exist. Someone simply chose not to check.",
            "**4. Are customer complaints feeding back into product decisions?** Corporate Ewa reported her issue in August. Her lawyer wrote in October. She went viral in December. Four months of clear signal was ignored. For every vendor who goes viral, dozens are swallowing the same problem quietly. Your support tickets, your customer reviews, your DMs, these are your product's feedback loop. If they are not informing roadmap decisions, you are flying blind and calling it focus.",
            "**What This Means If You Are Building Something**",
            "The back door in your product is probably not a hacker exploiting a bug. It is more likely a design decision made in a sprint that nobody went back to revisit. A verification step scoped out to protect conversion rates. A governance question was parked because there was a deadline. A complaint that went into a support queue and never made it to a product decision.",
            "Those decisions are still sitting in your product right now.",
            "**The question is not whether your product has gaps. Every product does. The question is whether you find them before someone else does.**",
            "*If you're not sure where your gaps are, that's exactly the kind of conversation we have with teams every week*",
            "[**Book a discovery call with the ProduqtEdge →**](/) *We will find the gap before the internet does.*",
        ]},
    {slug:"product-discovery-as-a-key-to-solving-problems", title:"Product Discovery as a key to solving problems",
        topic:"Product Management", type:"Article", date:"May 11, 2023",
        authors:["Yewande Sulaiman"], cover:pic("product-discovery-as-a-key-to-solving-problems-1.jpg"),
        summary:"User behaviours evolve, so do technologies, and markets. Discovery helps to validate that solution is fit for the problem and the user.",
        article:[
            "My last post about building products that solve problems highlighted four key inputs and contributions towards designing products to solve user problems.",
            "Discovery, Assumptions validation, Incremental building, and Data.",
            "Let's focus on discovery today.",
            {heading:"What is discovery?"},
            "Discovery is many things and addresses many perspectives. The aim of discovery is to understand the problem from the user’s perspective before solutioning. It’s important to note that discovery is an iterative and continuous process. User behaviours evolve, so do technologies, and markets. Going back to revalidate and learn about market changes is key to product success.",
            "It’s the process of researching a problem from the perspective of the problem owners (users) and validating the viability of assumptions that have been made with respect to this problem, taking into consideration the market realities, and making informed product development decisions.",
            "David Jonassen’s definition of problems as highlighted in an article by Theresa Torres is a great illustration of the kind of user problems that product managers encounter. Jonassen describes two kinds of problems – **structured** and **unstructured**. Structured problems typically have simple and direct solutions; in other words, they have single right answers. However, unstructured problems typically have multiple solutions depending on who you talk to and their context.",
            {heading:"So how can Product Discovery be done right?"},
            "I’ve identified these 5 key factors that contribute to successful product discovery.",
            {heading:"1. First, it’s important to define clear goals for the discovery as well as expected outcomes.", sub:true},
            "The goal of the discovery is pretty straightforward – to identify opportunities (pain points, gaps, nice to haves), and solutions to be developed.",
            "The outcomes, however, can be a bit dicey. This is because outcomes need to be aligned with the overall product goals which are derived from the overall business goals. It gets dicey because the product team may find it difficult to be objective and keep an open mind when crafting user interviews. The key outcome of product discovery is assumption validation but to ensure we’re on the right track, the assumptions need to be based on a correct understanding of the problem in the first place.",
            {heading:"2. Secondly, discovery is iterative and never ending.", sub:true},
            "We keep going back to the users and the market. User behaviours evolve, so do technologies, and markets. Going back to revalidate and learn from the market is the key to product success.",
            {heading:"3. Users are front and center of the discovery process.", sub:true},
            "Don’t be misled because this point is not the first on my list. Users are the most important contributors to this exercise. Not buyers, users. The people who interact with the product. The people whose problems we’re solving – users. Users must be involved in the entire process, they must be considered and actively listened to. Their feedback is what determines where the opportunities lie.",
            "Developing empathy for users and finding ways to help them articulate their needs without influencing them is most important. We also need user interactions to get over the ‘arrogance’ that comes from being familiar with our product. Solutions and actions that may seem obvious to us may be novel to the user. What’s more? Our solutions may be creating problems for the user. To ensure that we capture the right information, it’s important to take multiple steps back and put ourselves in the user’s shoes.",
            {heading:"4. Collaboration between product, design and technology teams", sub:true},
            "These three teams are the key components of a product development team. They feed off one another and help design products that solve real user problems.",
            {heading:"5. Documentation", sub:true},
            "Please. Keep. Records! The only way to know where we’re going is an improvement on where we’ve been is by knowing where we’ve been. Documentation can seem tedious but it is absolutely necessary for future reference.",
            "Now that we’ve identified the key ingredients, what steps can we take to guarantee successful Product Discovery?",
            "You’re familiar with frameworks and methods such as design thinking, story mapping, empathy mapping, assumptions mapping, usability testing, A/B testing etc. but I’m not going that route. Frameworks are great, but I prefer to approach things from action and results perspective.",
            {heading:"So, let’s look at 8 steps that will guarantee successful product discovery when done right."},
            {heading:"1. Understanding the problem", sub:true},
            "This is an initial exercise that helps you put things in perspective. Does the problem actually exist and what other ways could it be solved? To do this effectively, it’s important to embody the user and the problem as objectively as possible. This exercise helps the PM develop empathy for the user.",
            {heading:"2. Reviewing your Ideal Customer Profile", sub:true},
            "Whether you’re coordinating discovery for a new or existing product, reviewing the target market helps to confirm that we’re on track and building for the right users. Evaluate the previously defined personas and ICPs. Do your assumptions remain valid?",
            {heading:"3. Research", sub:true},
            "What is the competitive landscape? What is the market outlook? I wrote extensively about research in a few articles. This is a great place to start.",
            {heading:"4. Design customer engagement and data collection methods", sub:true},
            "The most common method for these include interviews, empathy mapping, assumptions mapping, usability testing, A/B testing etc.",
            {heading:"5. Collect and review the data", sub:true},
            "Once the collection methods are defined, the next step is to collect the data, evaluate it and start identifying opportunities. PMs have to be super objective when engaging users to collect data. For instance, during interviews, ask open questions, ask the same questions in multiple ways, actively listen and document.",
            {heading:"6. Identify and map opportunities to solutions", sub:true},
            "Opportunity-solution mapping is a great way to identify opportunities, map them to possible solutions as well as the business or product goals they may address. Mapping is generally a great mind tool that helps us structure our thinking.",
            {heading:"7. Prioritize the problems and solutions", sub:true},
            "Yay! We’ve successfully identified solutions to our users problems. But remember that the goal of product discovery is to eventually determine what to build and of course at this point, your opportunity map has quite a number of solutions. This is the point to introduce prioritization. Which problems are more important to the users? Which solutions are more viable than others? Which solutions are you able to deliver with the resources you have?",
            {heading:"8. Design the experiment", sub:true},
            "What’s next? Validate our assumptions through experiments. And then, learn and repeat.",
            "**Do you have questions about product discovery?** [Get in touch](mailto:yewande@produqtedge.com).",
            {heading:"Mentioned in this post:", sub:true},
            "David Jonassen’s definition of problems as highlighted by Theresa Torres [https://www.producttalk.org/2016/01/product-managers-level-problem-solving-skills/](https://www.producttalk.org/2016/01/product-managers-level-problem-solving-skills/)",
        ]},
    {slug:"are-you-building-products-or-solving-problems", title:"Are you building products or solving problems?",
        topic:"Product Management", type:"Article", date:"May 5, 2023",
        authors:["Yewande Sulaiman"], cover:pic("are-you-building-products-or-solving-problems-1.jpg"),
        summary:"Building products and solving problems should ideally mean the same thing, right? Well, not always",
        article:[
            "These two should ideally mean the same thing, right?",
            "Well, yes. But have you noticed a lot of products actually exist without solving real problems? When I come across these products, the first question that pops in my head is – Why?",
            {points:[
                "Why did they skip the most important step of product development – Discovery?",
                "Why did they choose to dive in headfirst without validating user needs?",
                "Why did they spend so much (well, it’s no longer expensive to build products anyway) building this pretty looking app that really has no USP?",
            ]},
            "I have so many questions but first I’d like to apologise for being out of commission for a while. Or should we pretend the last 6 weeks didn’t happen and skip to the good part? Naa. Retrospectives are good. I won’t bore you with the details though, especially since I already wrote about it [here](https://www.linkedin.com/posts/yewande-sulaiman_continued-activity-7049447210660376576-kPlI?utm_source=share&utm_medium=member_desktop).",
            "Ok! Just one more quick by the way – If you’ve developed a routine or habit, try as much as possible to stick with it. Gosh! I left regular writing for a few weeks, and it’s been a struggle getting back. But with you in my corner, I know we’ll get back in sync soon.",
            "*Done gisting. Back to products and solving problems.*",
            "So, what’s a typical ideation process? Let’s even leave the frameworks for now. How do people come up with solutions (read products)? They either encounter a problem in their own lives or around them and decide to solve the problem. Great! This is an ideal problem-solving approach. However, in a lot of cases, the solution is not commensurate with the product. Will the product solve the problem? Yes, but did we need that particular product to solve that problem? Probably not.",
            "Am I rambling? Sorry. I told you I’m rusty.",
            "Let me illustrate.",
            "So, let’s say we have identified a housing problem for a homeless person, and we want to solve that problem by providing him accommodation. To solve that problem, we decide to build a state-of-the-art mansion. Have we solved the homeless person’s problem? No!",
            "Lol. I can feel your eyes rolling – but the mansion does solve the accommodation problem.",
            "Well, the issue here is that we’ve used a gun to kill a housefly. Will the fly die? Probably, but there are two key issues with this approach–",
            {ordered:true, points:[
                "Cost of investment – we’ve expended a lot of resources to build this house that the homeless person doesn’t **need**.",
                "Time to market – dude is homeless! All he needed was basic shelter that could have been a makeshift shed with basic amenities. In fact, by the time we finish building our mansion, our client may have died of frostbite.",
            ]},
            "We clearly made assumptions of the user’s (homeless person) needs. Even though we had good intentions, and even if the product (the mansion) was ready early enough to provide value to the user, we most likely ended up confusing the user with too many options and they’ll probably be back on the streets in no time.",
            "So, what should we have done differently?",
            {heading:"1. Discovery!", sub:true},
            "Every product development framework emphasises discovery and that’s simply because we build products to solve problems for users. Users are the most important part of this equation. You don’t want to build a product that nobody wants to use. Discovery involves a lot of research, user engagement, empathising, analysis, and definition of user problems. The aim of discovery is to ensure that we understand the problem from the user’s perspective **before** we even begin to think about solutions. It’s also important to note that discovery is an **iterative and incremental** process. We need to keep going back to the user to validate our assumptions and test our hypotheses.",
            {heading:"2. Assumptions Validation.", sub:true},
            "There will always be multiple ways to solve problems. The best place to start is the simplest solution. This way, we can **quickly** identify the flaws in our assumptions and fix them or go back to the drawing board if required. Building a mockup or prototype helps us visualise the solution. Please note that I did not say MVP. A prototype or mockup gives a basic representation of what the product will look like. An MVP is a small step higher, but MVPs don’t necessarily need to be a version 1 of your product. For instance, your MVP can be an excel sheet and a google form!",
            "*I have an upcoming class on MVPs this month. It’s FREE. I’ll send you a link to sign up next week, so please mark my emails as important.*",
            {heading:"3. Incremental Building.", sub:true},
            "You thought Agile, didn’t you? Exactly. Solving the immediate problems first gives us clarity and helps us focus on the right things that the user actually finds valuable. For instance, building a 20-room-mansion for a homeless person doesn’t solve their immediate need and may not be of value to the user.",
            {heading:"4. Data!", sub:true},
            "Another key consideration for solving valuable user problems is the importance of data. Every kind of data is important – data from product usage, market data, competition data, user feedback, resource availability data etc. I say this all the time – data is a product manager’s most important weapon. We make informed decisions because we track and analyse data. Listen to the data, it will take you on a journey of a lifetime!",
            "ProduqtEdge helps companies build tailored product strategies, scalable products & product teams.",
            "Join our growing community of product managers, product leaders and founders for mentorship and coaching opportunities.",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
        ]},
    {slug:"whatiorderedvswhatigot---the-product-manager-job-function", title:"#WhatIorderedvswhatIgot– The Product Manager Job Function",
        topic:"Product Management", type:"Article", date:"Mar 6, 2023",
        authors:["Yewande Sulaiman"], cover:pic("whatiorderedvswhatigot---the-product-manager-job-function-1.jpg"),
        summary:"Need help hiring great product managers? Here is a cheat sheet to help you in 5 steps!",
        article:[
            "Despite defining moments in the history of product management, I believe we’re yet to scratch the surface of the complexities of the discipline. The job of a product manager continues to evolve as the discipline grows and organisations establish their definitions of what product management means to them.",
            "I’ve had the opportunity of engaging and working with hiring managers from startups of all stages as well as larger organisations and a lot of them seem to have similar feedback about their experiences with product management teams. I found it quite interesting that their feedback usually trends more towards negative than positive. They always seemed to have very high expectations that ended up getting ruined; very similar to **#whatIorderedvswhatIgot** scenarios in fashion. A quick review of PM job descriptions across diverse organisations reveals that a lot seem to be left to the interpretation.",
            "Not familiar with #*whatIorderedvswhatIgot*? It's a hashtag that was coined to describe a comparison of an original outfit order and the product that the customer received. Here’s a great example:",
            {image:pic("whatiorderedvswhatigot---the-product-manager-job-function-2.jpg"), caption:"*Tip: If you’re having a really bad day, just google the hashtag #whatIorderedvswhatIgot, I promise you a good laugh.*"},
            "So, why does it seem that hiring managers have different expectations of a PM’s job function from the PM’s understanding?",
            "I have a simple answer to this question but before I tell you my answer, let’s talk about some of the feedback I’ve received from hiring managers and organisation leads. I’ll let you guess which company size raised which issue. *(Hint: There are many right answers).*",
            {image:pic("whatiorderedvswhatigot---the-product-manager-job-function-3.png")},
            "*Did you enjoy doing the mapping? Awesome.*",
            {quote:"So, why do hiring managers and product managers seem to have different expectations and understanding of the role of a product manager, especially in startups – AMBIGUITY!"},
            "Ambiguity in defining the PMs role typically leads to misinterpretation which of course leads to *#whatIorderedvswhatIgot*. This is also a reflection of the general lack of convergence on the roles of product managers across industries and GTM strategies.",
            {heading:"Factors that influence the role of product managers include:", sub:true},
            {ordered:true, points:[
                "the company stage,",
                "the product stage of its lifecycle,",
                "the company size (team),",
                "how fragmented the product team is,",
                "and most importantly, the company’s GTM strategy.",
            ]},
            {heading:"Ambiguity goes both ways. I also took some feedback from product managers on ambiguity and other key issues from their experience.", sub:true},
            {points:[
                "Copy and paste JDs with unclear roles and responsibilities – **headless chicken syndrome.**",
                "**Even more headless chicken behaviour**– Your product vision is too convoluted – can we just choose a direction and focus please?",
                "Your onboarding was (almost) non-existent because **fire-fighter is your middle name and we want you to “hit the ground running”**",
                "You **don’t have a team to bounce ideas off** either because startup or IC in large company.",
                "You’re overwhelmed because everyone assumes your job includes everything from presales to support. **You’re the lead, the analyst, the designer, the no-code dev all rolled in one.**",
                "Because you’re so busy doing work that you really shouldn’t be doing, you have less time to do real product management and then your top-line go **“you’re not pulling your weight”. Errr, please, I’m pulling the weight of ten other people!**",
                "You don’t have enough time for R&D because **everything must happen NOW!**",
                "You have **minimal or zero access to market data** because 1- no time to conduct detailed customer engagement activities and 2 – org doesn’t pay for the required research tools.",
                "Your top-lines have you chasing metrics that don’t actually contribute to bottom line **(read vanity metrics).**",
                "Your company can hold meetings for Africa! **When do you even have time to execute?**",
                "You have no authority and not enough influence and your management is busy with the latest shiny initiative (which unfortunately isn’t your product or feature) so **no help from above.**",
                "Your team lacks representation at C-level meaning, **you are basically errand kids.**",
                "Your company takes ‘leading without authority’ to the next level. You have no say in key decisions and the small social capital you have is almost finished. You’re now best friends with the Domino’s phone admin because **na every Friday you dey buy pizza.**",
                "And my personal fave! The tech bro salary you were promised has **entered voicemail**.",
                "Oh! Let’s add this – Company-wide SAFE Agile adoption. **You said?!**",
            ]},
            {heading:"So, how can you avoid ambiguity in defining your expectations from product managers?"},
            {image:pic("whatiorderedvswhatigot---the-product-manager-job-function-4.jpg")},
            {heading:"Step 1 – Understand the job function.", sub:true},
            "As with any job, it is important to clearly understand the roles and responsibilities expected of the job function. There are multiple ways to approach this including:",
            {ordered:true, points:[
                "**Walking a mile in their shoes.** This is especially applicable to startups. As a founder, you embody the product vision. Sometimes, you need to play the part for some time to gain a deeper understanding and appreciation for the job function such that when you are ready to hire for the role, you are able to clearly articulate your expectations.",
                "**Research**. Read and learn about industry best practices, and tailor your job functions to fit your company.",
                "**Hire an experienced general to help you build an efficient team**. You can’t know everything and as founders and leaders, you have a lot taking your time. Hire experienced product leaders to help you build your front line team.",
                "**Outsource to industry experts like ProduqtEdge**. Because PM-as-a-Service organisations and communities engage with and operate between both employers and employees, we are uniquely positioned to understand your product needs and help you not only define tailored job descriptions and expectations but also help you populate your teams with qualified product managers that have been vetted and trained by our seasoned professionals.",
            ]},
            {heading:"Step 2 – Clarify the responsibilities of the job function.", sub:true},
            "Now that you have some idea of what a product manager’s job function is, the next step is to determine the job function of a product manager in your organisation depending on your company stage, your product’s stage in its lifecycle, the size of your team, your available budget, and your GTM strategy.",
            "I’ve found that an effective way to do this is by taking a bottom-up approach rather than a top-to-bottom approach. I’ll share my cheat sheet.",
            {ordered:true, points:[
                "First, I define my **product vision** from an AS-IS / TO-BE (Near future) / BHA-TO-BE (future future) perspective similar to [Janna Bastow’s Now/Next/Future Roadmap](https://www.prodpad.com/blog/invented-now-next-later-roadmap/).",
                "Then, I take all my learnings from **industry best practices** and create a long list of **tactical activities** required to achieve my product vision as well as a list of critical product management skills.",
                "Then I group these activities into activity types along the lines of the **critical product management skills**. *At this point, these tactical activities do not consider the stage of the product yet.*",
                "Now, I bring in **product strategy**. What is our approach to growth? Are we leading with the product, sales, community or marketing? Then I review my list from 3. And map the activity types required to execute our GTM approach.",
                "At this point, the PLC comes into play. I do a three-way mapping from the tactical activities to the GTM approach and the Product Lifecycle. As defined in my PM vs PLC model, the product needs vary as it progresses through the PLC which also reflects on the product managers.",
            ]},
            "This approach gives me a holistic view of what my product needs to go from AS-IS to BHA-TO-BE. It helps me clearly define the roles and responsibilities for each role which in turn helps to manage my expectations by defining OKRs and KPIs that are easy to measure. my team also has a clear understanding of what is expected of them and everyone is happy!",
            {heading:"What’s your approach to hiring product teams?", sub:true},
            "Hit me up if you’d like to chat - [https://www.linkedin.com/in/yewande-sulaiman/](https://www.linkedin.com/in/yewande-sulaiman/)",
            "ProduqtEdge helps companies build tailored product strategies, scalable products & product teams.",
            "Join our growing community of product managers, product leaders and founders for mentorship and coaching opportunities.",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
        ]},
    {slug:"market-research-in-product-management", title:"Market Research in Product Management",
        topic:"Product Management", type:"Article", date:"Feb 2, 2023",
        authors:["Hameedah Bamigbola"], cover:pic("how-to-use-competitive-analysis-to-build-successful-products-1.jpg"),
        summary:"Accurate market research can be a definitive differentiator between products in terms of market reception and overall success of the products.",
        article:[
            "*Finally! Welcome to the final instalment of this series. Did we bore you? I hope not. This instalment is written by a due diligence guru – ex-KPMG, now EY. Yeah. You’re in for some goodies. Enjoy!*",
            "YS.",
            "**“Data is the most important weapon in a PM’s arsenal”.**",
            "If you have been following us on this series, (and I hope you have!), you are familiar with this quote.",
            "Accurate market research can be a definitive differentiator between products in terms of market reception and overall success of the products. The market captures the interplay between the potential users of your products and the industry in which you operate.",
            "Conducting adequate research on the market helps you to refine your product and ensure that you are proposing to sell exactly what your users are interested in purchasing, which also provides additional value proposition relative to what your industry currently offers.",
            {heading:"So what is market research?"},
            "Market research involves a systematic and analytical approach to gathering sufficient information about trends and current state of your target market: the users, the competitors, the regulators, and all other stakeholders.",
            "Unfortunately, some product managers or startups fail to consider this aspect of product development and wonder why their products fail (regardless of fancy documents or other hypotheses upon which their products are based).",
            "A classic example of this is a recent conversation I had with someone who asked me why his business of selling rice and chicken at a carnival did not work out even though he had the right product for his target market *(Nigerians who looooove rice and chicken!)*, a seemingly large market, indirect competitors and a fancy “business plan”.",
            "I asked him a simple question – what do you do at a carnival?",
            "**To my surprise, he said he had never been at a carnival – he just heard from friends that they did not have access to enough food during the last carnival they attended.**",
            "From my experience in carnivals, people tend to march/dance along with the bands and performers so, naturally, snacks and finger foods would be the most convenient choice, right? Well…",
            "His “competitors” were selling snacks and finger foods inside the crowds, while maintaining their stalls as warehouses for their products! Without this understanding, he spent so much money producing inventory, hiring waiters and securing space for selling his merchandise because he assumed that since Nigerians (“the users”) like chicken and rice, we would like it under all conditions and in every situation – **WRONG**!",
            "He also incorrectly assumed that since other vendors (“the Competition”) were not selling our beloved rice and chicken, he had a unique value proposition which would resonate with his Users – **WRONG**!",
            {heading:"Key aspects of the market to consider during your research"},
            "With a strong background and understanding of the building blocks of the market – i.e., the user and competition, product managers must layer on a strong understanding of other components of the market in which they intend to operate.",
            {heading:"Product Managers must consider the following:"},
            {points:[
                "**Location/Channel**: How do you intend to reach your users, or more importantly, how do you expect your users to reach you? What is the ideal channel to sell your product to your target customers? What are your competitors doing? What can you do better?",
                "**Regulatory environment**: You may have a brilliant idea for a solution which your regulator deems inappropriate or illegal! Without resolving this hindrance, you cannot legally and successfully implement your brilliant idea.",
                "**Marketing channels**: Our Business Studies days taught us the four Ps of Marketing (Product, Price, Place, Promotion). This is the final piece of the puzzle for understanding the overall market. Understand every P as it relates to your industry to design and sell a winning product!",
            ]},
            "💡",
            "We have an awesome product panel coming up next week. We'll be discussing how to leverage Artificial Intelligence to become a better product manager. Of course product research is one of the key aspects we will discuss.",
            "[Sign me up for \"Leveraging AI to become a better PM\"](https://lnkd.in/d42AvEcy?ref=dishapages)",
            {heading:"Tools for Market Research"},
            "Several tools have been developed to guide you on your market research journey, each addressing key aspects and focus areas:",
            {heading:"SWOT Analysis:"},
            "This involves an assessment of the Strengths, Weaknesses, Opportunities and Threats in a market.",
            {points:[
                "**Strengths** and **Weaknesses** are internal in nature, helping you to get a thorough understanding of the proposed benefits of your potential product, as well as the areas in which there are currently challenges/weaknesses which your product may solve.",
                "**Opportunities** and **Threats** are more externally focused, helping you to assess other opportunities in the market (from existing weaknesses or ongoing trends), as well as potential factors which may threaten the success of your product.",
            ]},
            {image:pic("market-research-in-product-management-2.jpg"), caption:"SWOT Analysis"},
            {heading:"PESTLE Analysis:"},
            "PESTLE involves a detailed assessment of the Political, Economic, Social, Technological, Legal and Environmental landscape of the market in which you intend to operate.",
            {points:[
                "**Political** landscape covers regulatory pronouncements as well as other government factors (including potential support) which may contribute to the success or failure of your enterprise.",
                "**Economic** assessment involves a deep dive into the macroeconomic environment and how these may impact the success of your product. The most widely used metrics to assess the viability of the macroeconomic environment include GDP & GDP growth, Inflation, Interest rates, Exchange rates, FX reserves, Government spending/budget/debt etc.",
                "**Social** assessment highlights the individuals and households within your target environment. Relevant indicators include per capita disposable income, unemployment rates, poverty rates, age/gender distribution, literacy rate, mortality rates, etc.",
                "**Technological** assessment involves the review of existing technological advancements as well as technology requirements for your product and market.",
                "A **Legal** review will highlight licensing and other requirements for your proposed operations.",
                "**Environmental** reviews highlight any environmental factors, including requirements for aligning with ESG agreements, as well as a general understanding of the environment in which you will operate.",
            ]},
            {image:pic("market-research-in-product-management-3.jpg"), caption:"image src: https://business-docs.co.uk/scenario/how-do-i-do-a-pestel-analysis/"},
            {heading:"Other analytical tools which may support the different aspects of your market research include:", sub:true},
            {points:[
                "**Five WHYs** – which is especially helpful in drilling down on specific problems.",
                "**CATWOE** (Customers, Action, Transformation process, World view, Owners and Environmental constraints), which can be useful in transforming and refining your product design.",
                "**SCRS** analysis (Strategy, Current state, Requirements and Solution), which can be an important tool for assessing the industry and developing a product to solve any existing challenges.",
            ]},
            {heading:"Now that you have sufficient information about your market, what are the next steps?"},
            {ordered:true, points:[
                "**Incorporate your findings into your product design and development:** Take all the feedback from your potential users and refine your product in a way that addresses the users’ requirements, preferably in a manner that is not currently being addressed by your competitors.",
                "**Validate your assumptions and prioritize requirements and features based on market needs:** Listen to your potential customers – what do they want and how does your product address this? User surveys and testing can help you to eliminate unnecessary and expensive product features and improve your focus on customer needs and preferences.",
                "**Track your product’s performance in the market**: Conduct ongoing reviews and research on the industry and the market and compare with your initial hypothesis and KPIs. Without analytics, every product is as good as dead!",
            ]},
            "**Thank you for joining us on this series. I hope you’ve learned a thing or two.**",
            "💡",
            "Signed up for the product panel yet? **How to leverage Artificial Intelligence to become a better product manager.**",
            "[Sign me up for \"Leveraging AI to become a better PM\"](https://lnkd.in/d42AvEcy?ref=dishapages)",
            "We will work on making an ebook available for download soon so that all the information, guidelines and tools to help you become an expert product researcher can be at your fingertips.",
            "Follow our pages and join our community to be the first to know when it drops",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
        ]},
    {slug:"its-one-month-to-elections-is-your-product-fortified-against-disruptions", title:"It’s one month to elections, is your product fortified against disruptions?",
        topic:"Industry Trends and Analysis", type:"Article", date:"Jan 25, 2023",
        authors:["Yewande Sulaiman"], cover:pic("its-one-month-to-elections-is-your-product-fortified-against-disruptions-1.jpg"),
        summary:"7 change buffers that you can put in place to help you ‘react’ faster to sudden market disruptions.",
        article:[
            "It’s election day. You’re leisurely strolling to your polling booth, PVC in hand, feeling like a *G*, making a difference with your vote. You cast your vote for your preferred candidate, you watch everyone vote, you keep a stern watch over the ballot boxes and their handlers. You follow the ballot boxes as they are moved, watch as votes are counted. You record, share on social media, keep track of happenings at other polling booths in your local government, states and the country at large. From the looks of it, your candidate is definitely in the lead.",
            "All that talk about social media president seem to be just that – talk. *Hallelujah*! This is a new beginning for Nigeria. This is the Nigeria you believe in. This is the Nigeria you decided to leave ‘the abroad’ to come back and build. This is the Nigeria that…",
            "Hold up! INEC Chairman just came on Channels TV. Election results are inconclusive. They need to recount. *Hian*! They have come again *ooo*. You know what this means. You’ve been a Nigerian long enough. You spend the next few minutes shouting and cursing at all the politicians in the country. Then you resolve to become more active in politics going forward. *Yayyy* you!",
            "Oh wait! You remember you’re Product Lead at Innovative Startup Inc. *Ewoo*! What does this mean for your product?",
            {heading:"Possible election-related disruptions"},
            "I’ve highlighted a few possible disruptions and grouped them along these topics, so I don’t lose you.",
            {points:[
                "A – Logistics (we may have lockdowns)",
                "B – Insecurity and its fallouts",
                "C – Further devaluation of the naira",
                "D – Policy changes",
            ]},
            {heading:"A – Logistics (we may have lockdowns)", sub:true},
            "Thankfully, COVID lockdowns forced most people to optimise for remote work and access to services.",
            "Ensure everyone that needs to have access to whatever does, just in case we have another episode of #endsars.",
            {heading:"B – Insecurity and its fallouts", sub:true},
            {points:[
                "**Network (and other infrastructure) access** – we’ve experienced suspension of telecom and satellite services, electricity etc due to insecurity in the country. Now is the time to ensure that your cloud backup jobs are running, that you have enough diesel in your generator tank and any other proactive measures to mitigate against these possibilities.",
                "**Access to funds** – this is mostly applicable to fintechs who depend on incumbents to provide some of their services. Does your collection / suspense account have limits? Now may be the time to increase it.",
                "**Investor funding** – uncertainties around our elections is an easy trigger for investors. What are you doing to assure your investors? Has that last check been deposited? Setup check-in calls today!",
                "**Japa syndrome** – good talents continue to japa from Nigeria every day. You’re happy for them. We all are, but, err, business needs to go on. Beyond international japa, there’s also a possibility of local japa – people moving to less insecurity prone locations for this period to avoid stories that touch. For instance, I’m running to ijebu to hide in my mother’s house at least 1 week before the elections. Engage your team members and find out their plans. Ijebu ode has terrible network o! Team meetings may become a painful experience of “Can you hear me? I can hear you.”.",
                "**Increased fraud** – desperate times they say… you know the rest. There’s been a gradual increase in robberies, fraud and all sorts of evil acts. A prolonged lockdown (or fallouts from insecurity) may lead to more fraud attempts on your product. This is a good time to beef up security. *God no go shame us o.\n*",
            ]},
            {heading:"C – Further devaluation of the naira", sub:true},
            "The fear of dollar denominated OPEX is the beginning of startup wisdom. Take care of your OPEX. Do I need to say more about this? I don’t think so.\n\nOh! If you’re a startup founder that still pays staff in dollars, toh, good luck o. God is your strength.",
            {heading:"D – Policy changes", sub:true},
            "Policy changes can happen as a result of impending change in government, or in response to insecurities or other development.",
            "We have a lot of examples of these from recent times. The three most recent ones are –",
            {ordered:true, points:[
                "CBN licensed more players",
                "CBN domestic card scheme",
                "Cashless policy and New Naira notes",
            ]},
            {heading:"So, back to my question - Is your product fortified against disruptions?"},
            "Better safe than sorry. *Abi* how does that saying go?",
            "Our environment may experience even more volatility over the next few weeks. Product teams should ideally be proactive and innovative, not reactive, but there'll always be situations beyond our control.",
            "So, what are some **change buffers** that you can put in place to help you ‘react’ faster and easier when those letters drop?",
            "As always, I’ve grouped these into categories to make for an easier read –",
            {points:[
                "**Technology-Related**",
                "**Process-Related**",
                "**Relationship-Related\n**",
            ]},
            {heading:"▪️ Technology-Related"},
            {ordered:true, points:[
                "Configurable Variables - Structure your app components such that variable inputs are always configurable at the application layer.",
                "Microservices - Employing microservices helps to improve deployment, maintenance and testing. Yes, distributed systems are more complex, but the pros outweigh the cons for continuous deployment.",
                "Individual/Distributed components - Beyond taking a microservices approach for software development, it also helps to break your product into modules/components from use case or user type perspective.",
            ]},
            {heading:"▪️ Process-Related"},
            {ordered:true, points:[
                "**Pre-Approved Change Management Protocols** - Every organisation should have defined change management processes, and these should include contingency plans for sudden changes especially regulatory-dependent ones.",
                "**Defined sprint management tools and processes**. Do you know your team’s velocity? Can you correctly estimate deliverable timelines? How accurate have your story points been in recent times?",
            ]},
            {heading:"▪️ Relationship-Related"},
            {ordered:true, points:[
                "**Make friends in ‘the right places’**. One of your superpowers as a PM is information. Cultivate relationships with industry stakeholders, colleagues who work for competitors, thought leaders etc. Being in the know sets you apart and helps you deliver your 120% with minimal anxiety. Lol… of course the anxiety is not going anywhere, but at least you can reduce it.",
                "**Make friends in ‘the right places’**. No this is not a repetition. As a PM who ‘leads’ with influence and not authority, your internal stakeholders should be your best friends. TGIF hangouts with your devs, QAs, designers and everyone in between should be a regular occurrence on your calendar. *God no go shame us ooo.\n*",
            ]},
            "As we look forward to the upcoming general elections in Nigeria, please be vigilant and careful. May we come out at the other end with a better country and leaders who have the best interests of Nigerians at heart.",
            "*PS: my opening scenario was just that – a scenario. We pray to have peaceful and successful elections. May the best men and women for Nigeria and Nigerians win.*",
            "ProduqtEdge is building a growing community of product managers, product leaders and founders. We facilitate mentorship and coaching opportunities.",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
            "We help companies build tailored product strategies, scalable products & product teams. Our instructor-led trainings will be open to the public soon. You can save your seat by joining our waitlist.",
            "**Save my Seat!**",
        ]},
    {slug:"embedded-finance---the-answer-to-a-cashless-nigeria", title:"Embedded Finance – The answer to a cashless Nigeria?",
        topic:"Industry Trends and Analysis", type:"Article", date:"Jan 25, 2023",
        authors:["Yewande Sulaiman"], cover:pic("embedded-finance---the-answer-to-a-cashless-nigeria-1.jpg"),
        summary:"How to leverage embedded finance to influence user behaviour and build a successful cashless Nigeria by increasing financial inclusion.",
        article:[
            "The fintech industry has received enough shockers in the last few months to last a lifetime. Let’s look at some of the recent developments.",
            {ordered:true, points:[
                "CBN licensed more players",
                "CBN domestic card scheme",
                "Cashless policy and New Naira notes",
            ]},
            {heading:"1. CBN licensed more players", sub:true},
            "CBN has recently granted several PSHC and PSSP licenses. Read more about this on [Paymentlogue](https://www.linkedin.com/company/the-paymentlogue/). They’ve done a great job of dissecting the topic.",
            "But this is a good thing, right? I think so too.",
            "What does it mean for your product? More players in the ecosystem gives you more room for flexibility. You have more options for partnerships and an increased variety in offerings.",
            {heading:"2. CBN domestic card scheme", sub:true},
            "Omo!! Is this NIP all over again? I remember early 2012. Lol! I was a newbie digital banking product manager. Hmmm... let’s leave that story for another day *o jare*.\n\nNIP eventually became a success, but I keep wondering why regulators are competing with operators. But what do I know? I’ve never been Governor of anything talk less of a whole CBN. We already have a home-grown card scheme, why not support Verve and help them achieve Mastercard and Visa status? Again, what do I know?\n\nWe’re fighting cash like we don’t know the real problems with our ecosystem. Our top problems in my opinion are –",
            {points:[
                "Underlying infrastructure e.g. open banking – we need flexibility and access to underlying payments services to deliver innovative solutions.",
                "Consumer behaviour – how do we influence or change consumer behaviour without education?",
                "Government policies – how innovation-friendly are our policies?",
            ]},
            "Back to our upcoming unity card, there’ll be growing pains of course, but will this card scheme eventually become an alpha like NIP did? I’ll wait for my ogas Adedeji Olowe and co’s predictions.",
            "*Anyway, as we were –*",
            {heading:"3. Cashless policy and New Naira notes", sub:true},
            "The war against cash has been a long one, with the most recent developments being the cashless policies and naira notes redesign by CBN in December.",
            "Have you noticed changes in user behaviour? Has the way users interact with your product changed significantly?",
            "One of the top areas that have been affected is agency banking; well, the CICO variant. You know, the POS guys you see under umbrellas and in kiosks all around whose main offering is cash in/ cash out. Have you noticed a decline in those umbrellas? There are different ways to unpack this but maybe later.",
            "There are several opportunities and advantages of restricted cash though, one is **embedded finance**. How can you leverage embedded finance to influence user behaviour and drive growth?",
            "Not familiar with embedded finance? Ok. Let's make a quick segue into embedded finance (EF). Don't worry, we're not going technical. I just want us to explore EF from the perspective of how it can be a great outcome of CBN's cashless policies.",
            {heading:"Embedded finance (EF)", sub:true},
            "Embedded finance (EF) is one of the top technologies that are shaping the future of tech because it increases the amount of time users spend on your app. EF provides payment services within non-payment apps and allows users to carry out transactions end-to-end without leaving your app. The easiest example of EF is embedded payments (in-app payments). So, you book an uber ride and the app automatically debits your pre-saved card. You didn’t need to do anything extra. Shikena. That’s the basics of it.",
            "[Forbes](https://www.forbes.com/sites/forbesbusinessdevelopmentcouncil/2023/01/23/reshaping-access-to-financial-services-3-things-to-seek-in-an-embedded-finance-solution/#:~:text=Embedded%20finance%20uses%20a%20combination,non%2Dfinancial%20businesses%20or%20platforms.) says: Embedded finance uses a combination of banking-as-a-service (BaaS) functionality and application programming interfaces (API) to integrate bank accounts, payments, lending, investments and other financial products directly into non-financial businesses or platforms.",
            "Embedded Finance goes beyond payments. The goal is to serve the customer extensively, increase engagement, and create multiple streams of income without the user leaving the app.",
            {heading:"Some great use cases of embedded finance include –", sub:true},
            {ordered:true, points:[
                "**BNPL** – buy now pay later is lending embedded in unrelated services such as ecommerce, consumer goods, health etc.",
                "**Inventory financing** is also a great example of embedded finance. A growing use case is in supply chain management for FMCGs. (Ope Adeoye describes this excellently in our [#founderswhodared chat](https://youtu.be/3xvfhLImiuQ)).",
                "**In app credit** is another great use case of EF. A lot of apps now offer digital wallets where they store value that can be used for purchases within the app. Your wallet can hold things like cashback, rewards etc. Some even for as far as integrating services such as bill payments and airtime purchase so you can spend directly from your wallet.",
                "In some cases, you’ll find companies going beyond the app and offering loyalty (co-branded) **cards** that can be used outside of their apps.",
                "Other use case of EF include insurance on consumer goods, transport and logistics provided as add-on services, healthcare etc.",
            ]},
            {video:"https://www.youtube-nocookie.com/embed/3xvfhLImiuQ?rel=0&autoplay=0&showinfo=0&enablejsapi=0"},
            {heading:"How does embedded finance help you?"},
            "Two major ways –",
            {ordered:true, points:[
                "More **revenue** lines. By owning the customer, you become a stakeholder in the transaction chain which typically means you earn an income for the convenience you provide to your customers.",
                "More importantly – **data**! You own the customer end-to-end. You can learn from their behaviour e.g. spending habits. You can use this data to segment your market properly, offer tailored versions of your product, build partnerships based on your consumer database, or even sell this data to advertisers!",
            ]},
            "Embedded finance has a lot to offer and when implemented right, it can help to resolve identity issues by creating digital trails which in turn improves access to credit, insurance and increase financial inclusion.",
            "**Some awesome examples of fintechs who are deeply invested in driving embedded finance in Nigeria are –**",
            {points:[
                "OnePipe – [Grassroots banking (inventory financing)](https://onepipe.com/grassroots-banking/)",
                "Flutterwave – [Fintech as a Service (account services)](https://www.flutterwave.com/us/faas)",
            ]},
            "ProduqtEdge is building a growing community of product managers, product leaders and founders. We facilitate mentorship and coaching opportunities.",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
            "We help companies build tailored product strategies, scalable products & product teams. Our instructor-led trainings will be open to the public soon. You can save your seat by joining our waitlist.",
            "**Save my Seat!**",
        ]},
    {slug:"how-to-use-competitive-analysis-to-build-successful-products", title:"How to use competitive analysis to build successful products",
        topic:"Product Management", type:"Article", date:"Jan 19, 2023",
        authors:["Yewande Sulaiman"], cover:pic("how-to-use-competitive-analysis-to-build-successful-products-1.jpg"),
        summary:"How to use competitive analysis to define product strategy and build successful products.",
        article:[
            "*At this rate, we’ll have to publish an ebook soon to discuss the multiple aspects of research in product management so that you’re not hopping from article to article when you need the information. What do you think?*",
            "Ok. Let’s get into it.",
            "We started discussing competitive analysis (competition research) here. Should I do a recap? Maybe a short one. No point repeating stuff you already know right? Plus, you can always do a quick review of the earlier articles. so I’ll just highlight a few things to refresh your memory or in case you missed it –",
            {ordered:true, points:[
                "Competition research is important for your product to even have a chance to succeed. You need to know who your competition is and what they’re doing to gain the market share you so desperately need.",
                "There are different types of competitors, and you need different strategies to address them.",
                "There are multiple ways to identify your competitors. We highlighted five (5) of them including **google search**, actively listening to your **customers** and prospects, using **social media**, checking **app stores**, and leveraging **existing research**.",
                "Once you’ve identified your competitors, you should focus on seven (7) key aspects to get useful information about them. These are their **vision**, their **USP and key offerings**, their **brand identity,** their **SWOT**, their **team**, their **infrastructure**, their **customers**. Other aspects that can help you have a holistic view of your competitors include their **pricing**, **staying power** (how large is their war chest?), **revenues**, workplace **culture**, **marketing** efforts, **metrics** such as CAC and LTV and a host of others.",
            ]},
            "I’d recommend you also take a quick look at the first article in the research series where we discussed why data and research are important to product managers.",
            "So now that we’ve identified competitors and categorised them, the next step is to find information about them around the **seven (7)** aspects we highlighted.",
            {heading:"How to find data about your competitors."},
            "There are several sources for finding data about these 7 key aspects of your competitors we highlighted above.",
            {ordered:true, points:[
                "**Company websites**. The first and easiest place to find information about a company or product is their website. This is where they put their best feet forward (well, in most cases). You’ll find information such as **(a.)** their vision, mission and core values. Vision statements are futuristic, and they tell you where they see their product going. Strategy is informed by vision and tactics are informed by their mission. By dissecting their vision and mission statements, you’ll learn how they think, how they want their customers to perceive them, and how they measure the success of their product or organisation (for multi-product organisations). **(b.)** customer reviews. You’ll want to take these with a pinch of salt however since they’ll only put great reviews on their website, but this is a good starting point to understanding how their best customers see their products. **(c.)** their user experience. Your experience of their website tells you what they focus on. Are they UI focused or UX focused? The experience you have from their website will most likely be the same you get with their product(s).",
                "**Product reviews**. You definitely want to teardown your competitors’ products. Get in there. Use their products, get to know their products intricately. You can only improve on what you know. Remember to put yourself in your customers’ shoes when you explore your competitors’ products. Your aim is to figure out how they (competitors) solve your customers’ problems. This is how you get an edge over them.",
                "**Customer feedback**. Find out what users say about your competitors. Keep up with social media and app stores especially. Dig deeper than just the comment or review, find the people behind the comments. Do they fit your defined personas? Are there new user groups you hadn’t originally included in your persona definitions?",
                "**News**. Keeping tabs on news (and gossip) about your competitors, your industry at large and the entire market is very important when trying to stay ahead of the curve. You don’t want to be launching features that some event that happened a week ago has rendered useless.",
                "**Marketing channels**. Their social media channels and other touchpoints tell you more than how many followers they have. Follow your competitors. Engage with their content so that algorithms suggest them and similar companies / products to you. Engage with their followers, you’ll not only get information about the competitors, you’ll also get conversion opportunities!",
            ]},
            "Now that we’ve identified **what** data you should be looking for and **where** to find them, let’s talk about **how** to collect, curate and use the data.",
            {heading:"How to collect, curate and use data from competitor research"},
            "There are several tools and templates that have been developed over time so I’m not going to reinvent the wheel. However, beyond just giving you a list of tried and trusted templates, it would help to evaluate these methods from the perspective of intended outcomes. I always approach every aspect of product management with the product lifecycle in mind.",
            "To successfully achieve competitive advantage, it’s important to identify your **why**. What are your **preferred outcomes**? Your outcome should be directly related to the stage of your product and your current positioning in the market.",
            "We developed the model below that identifies the needs of a product through the different stages of the product lifecycle. Read more about our PM vs PLC model.",
            {image:pic("choosing-the-right-product-manager-for-your-product-5.jpg"), caption:"ProduqtEdge Pm vs PLC Model"},
            "Understanding what your product needs at its current lifecycle stage helps to determine what to focus on during your competitive analysis.",
            {image:pic("how-to-use-competitive-analysis-to-build-successful-products-3.png"), caption:"ProduqtEdge Product Management Framework"},
            {heading:"PLC Stage: Development and Introduction", sub:true},
            "At this stage, your product is undergoing ideation, validation, creation and launch as seen in our product management framework above. Your team is working to validate the idea using different methods including delivering an MVP, launching to your target market and gaining early adopters. Your focus at this stage is awareness and adoption. You need people to use your product, give you feedback and become advocates.",
            "So how does competitive analysis help you here? With data from your competitors, you can identify personas, use cases, features that add value, pricing, channels to reach your prospective users and a lot more.",
            "Ideal templates for competitive analysis at development and introduction stage are high-level tools that focus on the top-level information characteristics and capabilities of your competitors.",
            {ordered:true, points:[
                "**SWOT Analysis**. SWOT is an acronym for Strengths, Weaknesses, Opportunities and Threats. This is a great way to evaluate your competitors from a holistic perspective with respect to the market you are playing in. This works best if you do a SWOT analysis for each of your top competitors, then compare to find similarities. The similarities help you identify common issues across your competitive landscape.",
                "**Competitive Landscape**. This is a quadrant chart that helps you identify how you position in comparison with your competitors. It’s important to figure this out early in your PLC as your positioning determines how you articulate your USP, communicate your value to your customers and which competitors to focus on battling for market share.",
                "**Competitor Overview**. This gives you a snapshot overview of your competitors along the key aspects we defined above. A great tool for this is the Product Canvas.",
            ]},
            {heading:"PLC Stages: Growth and Maturity", sub:true},
            "At this stage, you are optimising your product. It is expected that you have found product-market fit and are now adapting to market needs.",
            "Ideal templates for competitive analysis at growth stage are tools that focus on feature comparisons and customer feedback.",
            {ordered:true, points:[
                "**Product Reviews**. Understanding your competitors’ product is one of the most effective ways of achieving competitive advantage.",
                "**Competitor scorecard tools**. Once you’re familiar with their products, you are then able to incorporate tools such as Features Comparison, Kano Model, and Capabilities Matrix, BCG Matrix, G2 category Grid and a lot more.",
            ]},
            {heading:"PLC Stage: Decline", sub:true},
            "At decline stage, you are evaluating what your product needs. Is it due for sunsetting or a pivot? At this stage, you’re basically back to ideation so the same tools and methods you used to achieve competitive advantage at introduction stage apply here.",
            "**Purpose-Driven Research**: Before embarking on any form of research, it’s important to know your why. Why determines how and helps you tailor your focus to activities that generate impactful results.",
            "Now that you have –",
            {points:[
                "identified your competitors,",
                "the right data to research and collect about them,",
                "where to get information about your competitors,",
                "how and when to collect this information,",
            ]},
            "The next step is to use the data you’ve collected to inform your product decisions and create competitive advantage for your product and organisation.",
            {heading:"How to convert data into strategy", sub:true},
            "We introduced Michael Porter’s three strategies for achieving competitive advantage – cost leadership, differentiation and segmentation – here.",
            "Deciding how to compete depends on a lot of inputs such as your company size, your war chest, your capabilities and the existing competitive landscape.",
            {heading:"We discuss Product Strategy in detail in our course which teaches you everything you need to know about creating winning strategies for your product. Our Product Strategy course teaches you –", sub:true},
            {points:[
                "how to collect the right data,",
                "how to convert the data to valuable information,",
                "how to leverage information to influence stakeholders,",
                "how to develop great strategies and actionable goals,",
                "and how to achieve competitive advantage by learning from real life successful product leaders.",
            ]},
            "Until now, our trainings have been on-demand and in closed sessions tailored to our clients' products but I've got good news!",
            "We are working to open them up to everyone. Yayyy us!! You can secure your spot here. We like to have small classes for maximum impact.",
            "**Save my Seat!**",
            "Join our community and follow our channels to be the first to learn when we announce them.",
            "[Join ProduqtEdge Community](https://join.slack.com/t/produqtedge/shared_invite/zt-1nkbt3grk-dgjuliCMxuQ7NTm81DESiw)",
        ]},
    {slug:"research-in-product-management---competition-research", title:"Research in Product Management – Competition Research",
        topic:"Product Management", type:"Article", date:"Jan 11, 2023",
        authors:["Yewande Sulaiman"], cover:pic("how-to-use-competitive-analysis-to-build-successful-products-1.jpg"),
        summary:"How to use competitive analysis to understand your competitive landscape, define competitive advantage and build successful products.",
        article:[
            "In the first article of this series, we talked about the importance of data to product management and the role that research plays in a product manager’s life. In case you missed it, here’s a quick summary.",
            "Data is the single source of truth. Product managers mostly lead by influence, not authority which means that, they require stakeholder buy-in to make decisions such as what to build, when, and for whom. Beyond stakeholder engagement, they also need data to validate their assumptions, effectively predict the future and measure the success of their products.",
            "Data-driven PMs are those who consistently pay attention to important information in relation to their markets including their industries, users and competitors. We defined these terms as below:",
            {points:[
                "**Competition** refers to companies that provide services or products similar to yours. Your competition serves the same market as you. For example, Paystack and Flutterwave offer similar products within the same markets.",
                "**Industry** refers to a group of companies that offer similar products, solving the same problems. For example, fintech industry provides financial services through technology. Flutterwave, Paystack, Interswitch, and similar companies make up the fintech industry in Nigeria.",
                "**Users** are the people who use your product. There are different categories of users. For instance, for B2C products, your users are also your buyers, while for B2B products, you may have users who aren’t buyers.",
                "**Market** is a combination of the industry and users. Economists define market as a place where value (good and services) are exchanged. Markets are typically categorised by demographics such as geography, age, gender etc., and quantified in relation to the general population. For instance, the Nigerian market.",
            ]},
            "Now, let’s talk about competition.",
            {heading:"First, who are your competitors?", sub:true},
            "Your competitors are companies that serve the same market as you and offer similar products as you. There are different types of competitors, some more *important* than others. Not to confuse you, every competitor is important, but depending on factors like your company size, and product stage, and market type, you’ll need to pay attention to specific types of competitors more than others.",
            {points:[
                "**Direct Competitors :** These are companies that sell the same products as you **and** serve the same markets. They may have slightly different variations of your product, but their product clearly solves the same problems yours does and offers similar value to consumers. These are the companies that first come to mind when you think of your competitors. If you were to draw a 4-Quadrant competitive analysis matrix, they’ll be in the same box as your company. Let’s use food examples because everybody eats right? Labule is a local themed restaurant chain in Lagos, Nigeria. They’re known for their amala (abula). Their direct competition include – Olaiya, Yakoyo, White House, Amala Yahoo etc. These businesses all have similar offerings – they are mid-level restaurants that sell local food as fast food. Some of them position differently, for instance, Labule positions as a spot for the ‘cool’ crowd, some incorporate varieties into their menus, but at the core, they all offer very similar products and serve the same niche.",
                "**Indirect competitors :** These are companies that offer products that solve the same problems but not the same products as you per se. Continuing with the example above, Labule’s indirect customers are other restaurants who don’t necessarily carry the same products (in this case, amala) but they sell food, which solves the problem of feeding hungry people. Examples of Labule’s indirect competitors include Bukka Hut, BlackBell, Chicken Republic etc.",
                "**Replacement Competitors** : These are companies that offer products that can serve as an alternative to yours. Examples of replacement competitors for Labule are healthy food restaurants, food delivery services with no physical locations, etc. The main difference between replacement and indirect competitors is usually in how they solve the problem. Labule’s indirect competitors are basically restaurants with physical locations and varied menus, while their replacement competitors solve the same problem of feeding hungry people by delivering to their homes or feeding a specific niche who have specialised needs.",
                "**Potential Competitors** : These are companies that are not yet your competitors but have the capabilities to offer products similar to yours. They currently exist and serve the same markets as you, but they don’t offer products like yours yet. They have a low barrier of entry. Example of Labule’s potential competitors are grocery stores that sell the raw versions of the food.",
            ]},
            {heading:"Once you’ve identified your competition, it’s important to figure out your competition strategy. How do you intend to compete?", sub:true},
            "Michael Porter identified three strategies for achieving competitive advantage – cost leadership, differentiation and segmentation.",
            {points:[
                "**Cost leadership** means pursuing the efficiencies of economies of scale with aims of achieving the lowest possible production costs. The end game is to offer your products at the lowest market prices.",
                "**Differentiation** means creating a unique selling point that sets you apart from your competition. Differentiation can be achieved through brand identity, product value and quality, or having an exceptional team. The end game is to create a perception of value to your consumers that transcends the impact of your price.",
                "**Market segmentation** means serving specific niches. You’re building products that solve specialised problems. This can also be thought of as a form of differentiation but focused on a niche market segment.",
            ]},
            "*Here’s a great* [*summary*](https://edisciplinas.usp.br/pluginfile.php/5045811/mod_resource/content/1/Porter_An%C3%A1lise%20da%20Ind%C3%BAstria_Resumo.pdf) *of Porter’s competitive strategy and Five Forces.*",
            {heading:"Why and when should you research your competition?", sub:true},
            "Every product aims to succeed by whatever metrics are in line with its defined vision. To succeed, the product needs to have a competitive advantage. Defining your competitive advantage requires you to understand the competitive landscape in the first place. A great framework for evaluating the competitive landscape is Porter’s work on forces driving industry competition. He identified 5 forces that affect competition in any industry –",
            {points:[
                "Threat of new entrants",
                "Bargaining of buyers",
                "Bargaining of suppliers",
                "Threat of substitute products",
                "Rivalry among competitors",
            ]},
            {heading:"So why should you research your competition? The answer is obvious right? To achieve competitive advantage.", sub:true},
            "When should you research your competition? Every time!\n\nWhether you fear new entrants in your industry, or economic realities are predicting a shift in bargaining power of buyers and/or suppliers, or you fear the threat of your competitors, keeping tabs on what your competitors are doing is always important.\n\nEvery product manager must (yes, must) be a master at analysing their competing products and figuring out how to get a leg up in line with their product and company vision.",
            {heading:"How to identify your competitors.", sub:true},
            "Earlier we mentioned direct competitors are those who jump to mind when you think about your competitors. Beyond these top guys, we’ve identified **5 ways to identify your competitors.**",
            {ordered:true, points:[
                "**Google search**. One of the easiest ways to find your competitors is by doing a google search.",
                "Actively listening to **your customers** and prospects will usually give you insights into their alternatives.",
                "Use **social media**. Posts about the problem your product solves will mostly give you ideas of who your competitors are. Checking the social media pages of known competitors will also influence the suggestions that the algorithms show you.",
                "Check **app stores**. App stores will typically show you alternatives for any product you search.",
                "Find and leverage **existing research**.",
            ]},
            {heading:"For a successful search, you should", sub:true},
            {ordered:true, points:[
                "Put yourself in your customers’ minds. What will they type into the search bar? Think about this from the perspective of the problem they’re looking to solve. For instance, to find Labule’s competitors, you’ll probably type – *amala spots in lagos*.",
                "Do a keyword research. Use Keyword research tools like [Google Keyword Planner](https://ads.google.com/home/tools/keyword-planner/) to find top keywords for your product or industry.",
                "Search for your brand or product alternatives. E.g. Labule alternatives, amala alternatives",
                "Search for alternatives to your known competitors. E.g. Yakoyo alternatives",
            ]},
            {heading:"What information about your competitors should you pay attention to?"},
            "Without a strategic approach to competitive analysis, you are likely to be overwhelmed with a lot of data. Focusing on every information you come across can be counterproductive. You want to pay close attention to key information that actually contributes to your competitors’ advantage. Remember the purpose of this exercise is to figure what they’re doing better or worse and how you can learn from their mistakes and/or get ahead of them by gaining more of the market share.",
            "Below are **7 key aspects** of your competitor you should focus on to help you understand the key contributors to their competitive advantage.",
            {ordered:true, points:[
                "Their **vision**. A company’s or product’s vision tells you where they’re going, what problems they’re trying to solve, how they measure success and how they want their customers to perceive them.",
                "Their **USP**. A product’s unique selling point is that thing that makes it valuable. Understand how their customers value them by analysing their USP. Understand how they want their customers to perceive them by how they craft their USP.",
                "Their **brand identity**. The value of a brand contributes largely to the rate of adoption of their products. If your competitor has high brand equity, chances are they require less effort to gain more market share.",
                "Their **SWOT**. What are their strengths and weaknesses? What opportunities and threats affect them. You’ll be surprised at how these will differ by company even though you’re in the same industry and serve the same markets.",
                "Their **team**. This is usually covered in SWOT, but we’ve called it out because it needs special focus. Teams make or break products and organisations. Pay attention to the people they hire – their past experiences, their successes and failures.",
                "Their **infrastructure**. In the case of tech products, your competitors’ technology stack is one of the most important aspects to evaluate them on. Their ability to out-build you is dependent on their infrastructure and their team. Learn what they have and how they use it!",
                "Their **customers**. Users are the single source of truth for any product. Find out what their customers say about the product. Check reviews. They almost never lie (except when they’re doctored 🤣).",
            ]},
            {heading:"How to find information about your competitors."},
            "There are several sources for finding information about these 7 key aspects of your competitors we highlighted above.",
            {points:[
                "Company websites.",
                "Product reviews.",
                "Customer feedback.",
                "News",
                "Marketing channels",
            ]},
            "Join our community to stay informed, meet PM professionals and get access to mentoring and coaching opportunities.",
            "[Subscribe Now](https://produqtedge.substack.com/subscribe)",
            {heading:"The next instalment of this series will explore"},
            {points:[
                "*more on finding information about competitors*",
                "*tools and methods for effective competitive analysis (also called competition research),*",
                "*purpose driven competition research and ideal templates and techniques for specific outcomes,*",
                "*converting the data into strategy*",
            ]},
            "Did you find this article useful? Visit and subscribe to our [blog](/insights) for more product and industry insights.",
            "**ProduqtEdge** partners with organisations to achieve impact through value-driven and innovative products by empowering their product teams. Want to learn more about what we do, we are just an [email](mailto:info@produqtedge.com) away.",
            "Got questions about this article or comments you’d like to discuss, please share in the comments section and / or catch up with us on social media @produqtedge.",
        ]},
    {slug:"choosing-the-right-product-manager-for-your-product", title:"Choosing the right product manager for your product",
        topic:"Product Management", type:"Article", date:"Dec 6, 2022",
        authors:["Yewande Sulaiman"], cover:pic("choosing-the-right-product-manager-for-your-product-1.jpg"),
        summary:"Hiring a product manager can be like buying a book. You’ve read the reviews, the synopsis, maybe even the first chapter. Yet, no matter how much pre-purchase research you do, you can’t read the entire book before making that purchase.",
        article:[
            "Due to the blurry lines around the product management discipline, responsibilities of and expectations from product teams, hiring a product manager can be like buying a book. You’ve read the reviews, the synopsis, maybe even the first chapter. Yet, no matter how much pre-purchase research you do, you can’t read the entire book before making that purchase.",
            "Googling product manager skills or competencies for example will get you feedback like the list below:",
            {points:[
                "*Research (user, markets, industry)*",
                "*Prioritization and roadmapping*",
                "*Design knowledge (knows what good design looks like)*",
                "*Documentation (PRDs, user journeys, battle cards etc)*",
                "*Data analytics*",
                "*A/B testing*",
                "*Ability to take ownership*",
                "*Business development*",
                "*Budget and resource management*",
                "*Strategic thinking*",
                "*Communication and negotiation*",
            ]},
            "*This list can go on.*",
            "There's a ton of literature on how to hire great product managers discussing perspectives such as– core competencies, cultural realities and personalities, mindset and attitude, interview and screening processes, etc. ‌",
            {image:pic("choosing-the-right-product-manager-for-your-product-2.png")},
            {heading:"‌These perspectives, however, don’t help in answering the high-level question– what type of PM should you be looking for?", sub:true},
            "The product is not stagnant as it spans across a lifecycle, and its needs vary across the PLC stages. Having been privileged to help build and develop product teams across several organisations, we've identified **a key ingredient for finding the right PM– the understanding that products have different needs across their lifecycles**.",
            {heading:"In choosing the right PM fit for a product, it’s important to ensure"},
            {ordered:true, points:[
                "alignment between the organisation and individual on vision, goals and expectations,",
                "alignment of organisation culture and individual personality fit,",
                "and most importantly, as I’ve come to realise over the last few years across different roles as individual contributor and people manager, alignment of the product stage and the product manager / product team.",
            ]},
            "**To achieve this alignment, we’ve taken a top-down approach to finding Product-Manager-fit that has helped us build great product teams for our clients.**",
            "First, we define a detailed job description based on–",
            {ordered:true, points:[
                "what your product/team requires at that time. Products require different team dynamics as they go through their lifecycle of ideation to sunset.",
                "your organisation’s dynamics with respect to the product team. For instance,",
            ]},
            "a. How much authority and/or autonomy does your product team have?",
            "b. Does the product team feed into engineering or is it the other way around?",
            "c. Does your organisation have chief level sponsor for product management?",
            "d. Is your product team responsible for direct sales, presales or sales support?",
            "Answering the first question helps to determine at high level, the kind of product team you need to build. Answering the second question helps you design detailed expectations including core competencies, hard and soft skills, technical skills, background, experience, and most importantly, detailed job descriptions.",
            "In trying to answer the question of what your product requires at each stage, it helps to **evaluate the goal of each product stage**. ProductPlan does a great job of highlighting this as seen below.‌",
            {image:pic("choosing-the-right-product-manager-for-your-product-3.jpg"), alt:"Grid showing different roles of product management based on stages of the product lifecycle", caption:"[https://www.productplan.com/learn/product-management-role-product-lifecycle/](https://www.productplan.com/learn/product-management-role-product-lifecycle/)"},
            "‌*The product evidently has different goals and needs across this journey to help it achieve and/or maintain success. So why approach building PM teams from a one size fits all perspective?*",
            {heading:"We identified 4 characterisations for product managers across the stages of the product lifecycle."},
            {ordered:true, points:[
                "**The Curious PM** – this PM is all about the WHAT and WHY. They’re neither ashamed nor proud to ask tough and seemingly stupid questions. In truth, there is no stupid question anyway! The great thing about a curious PM is that they stay on trend, they learn effective research methods and are very data-driven.",
                "**The Resourceful PM** – the resourceful PM is that PM that finds a way around stuff. They don’t necessarily know the answers right off the bat, but they’ll keep trying and ‘harassing’ people until they figure it out. This PM is a great addition to any growing team. This PM is your go to guy for just about anything! This is not because they are absolutely great at everything (is anyone really?) but they understand their ‘limitations’, so they advocate for and leverage collaboration to achieve results.",
                "**The Networker PM** – this is your PM for opening doors and windows and maybe even cracking ceilings! They’ve built great networks across industries and markets over the years and they’re able to leverage this network to make things happen. It’s key to note here that the value of this network is mostly subjective and should be evaluated in line with the needs of the product.",
                "**The Executor PM** – there is no success without execution. Execution PM gets the job done. They move mountains to make things happen and they’re happy doing it. Their excitement is contagious, and you can easily tell they love what they do. Although as the PM grows in their career, the expectation is for them to become more strategy focused than execution focused.‌",
            ]},
            "‌*We ran a quick poll asking about 30 product leaders in Africa what they look out for when hiring product managers. We asked them to choose between* **Curiosity** *and* **Resourcefulness***.‌*",
            {image:pic("choosing-the-right-product-manager-for-your-product-4.png"), caption:"Poll results for curiosity vs resourcefulness"},
            "‌*The result was a landslide in favour of curiosity. It is interesting to note that most of these product leaders chose curiosity even though we deliberately provided minimal context in the poll. The participants are leaders and hiring managers across multiple industries including fintech, logistics-tech, health tech, edtech and ecommerce, with portfolios of products across different PLC stages.*‌",
            {image:pic("choosing-the-right-product-manager-for-your-product-5.jpg"), alt:"TimelineDescription automatically generated with medium confidence"},
            {heading:"Our PM vs PLC model highlights the product’s needs and the product manager best suited for each stage."},
            "**1. Development & Introduction Stage**– at this stage, you’re experimenting. With agile frameworks, development and introduction are simultaneous and the goals for the product at this stage mostly revolve around shipping and early adoption.",
            "**What kind of PM does your product need?**",
            "Your product needs a PM who is extremely curious and is willing to question the status quo. They should also be resourceful and have some network depending on their level of experience. As products at this stage are more common in startup environments, where you typically lean product management teams, curiosity is even more important as the PM’s curiosity will become a driver for other skills they need to succeed. They should question and be genuinely interested in understanding everything from plan to process to execution.",
            "**Tell-tale signs of the Curious Product Manager**",
            {points:[
                "They ask for clarification when they don’t understand the question",
                "They are always interested and excited",
                "They are self-motivated",
                "They know about random details, even those unrelated to their jobs",
                "They hold their own in conversations",
            ]},
            "**2. Growth stage** – at this stage, you’ve launched and are working towards growing adoption and generating ROI. The product needs to stabilise in terms of process and product-market fit. The model highlights resourcefulness as most important for this stage. The product team is expected to grow in seniority and experience alongside the product itself and the team’s dynamic should reflect this in order for them to achieve the expected impact.",
            "**What kind of PM does your product need?**",
            "Your product needs a PM that will move mountains to make things happen. As described above, the Resourceful PM doesn’t always know all the answers, but they are willing to keep trying out options and asking for help until they find a solution. This is the PM that will open up new revenue lines for your product, get competition data no matter how difficult to achieve competitive advantage. They will find ways to motivate their teams, and relevant stakeholders to ensure their product receives the attention and priority it requires. They are also climbing up the ladder and building networks to support them and grow their products.",
            "**Tell-tale signs of the Resourceful Product Manager**",
            {points:[
                "They are confident but not arrogant",
                "They are open minded and explorative",
                "They are proactive",
                "They are resilient",
                "When you ask, can we get this done? Their answer is always, YES!",
            ]},
            "3. **Maturity stage** – a mature product is one that has reached steady state. You have achieved market recognition and competitive advantage; you’re not spending as much on marketing or growth tactics. The product has reached its plateau.",
            "**What kind of PM does your product need?**",
            "A product at maturity stage needs a strategic PM. Just like the growth stage, this PM needs to be quite resourceful but more importantly, they should have built a good network that they can call on for help and direction. They’re experienced enough to understand the big picture and are always plugged in.",
            "**Tell-tale signs of the Networker Product Manager**",
            {points:[
                "They are great listeners",
                "They ask questions",
                "They’re not easily flustered",
                "They have a can-do attitude",
                "They are authentic",
            ]},
            "4. **Decline stage** – at this stage, there are multiple options for the product. It can be diversified, repositioned or sunset. You need a PM here that has access to markets, information, people and other resources to help determine the next steps for the product. This PM is more strategically inclined and is definitely quite experienced.",
            "**What kind of PM does your product need?**",
            "A product at decline stage has similar needs to one at maturity stage. The key thing here is having someone at the helm of things who is well informed so they can make strategic decisions on the next steps for the product.",
            "**The Executor PM** is not mapped to a specific stage because curiosity, resourcefulness or network without execution is zero. The model assumes all PMs are executors and / or have executors within their teams.‌",
            {image:pic("choosing-the-right-product-manager-for-your-product-6.png")},
            {heading:"The PM vs PLC model does not discount any skill across the product lifecycle, but helps product leaders zoom in on the high-level requirements for their product teams at each stage of the PLC."},
            "It is important to highlight that adopting this model without–",
            {points:[
                "correctly identifying the product stage,",
                "realistically identifying the must-haves and nice-to-haves in candidates, and",
                "creating environments that allow candidates to flourish during the hiring process,",
            ]},
            "–may not achieve optimal results.",
            "Overall, we acknowledge the fact that building a team is an art that takes time, patience and commitment to perfect.‌",
            "‌",
            "**ProduqtEdge** *partners with organisations to deliver value-driven and innovative products by empowering their product teams. Want to learn more about what we do, we are just an* [*email*](mailto:info@produqtedge.com) *away.*",
            "*Got questions about this article or comments you’d like to discuss, please share in the comments section and / or catch up with us on social media* [*@produqtedge*](https://twitter.com/produqtedge)*.*",
            "*Visit our* [*blog*](/insights) *for more product and industry insights.*",
        ]},
    {slug:"of-pivoting-in-the-face-of-reality", title:"Of Pivoting in the Face of Reality",
        topic:"Industry Trends and Analysis", type:"Video", date:"Nov 1, 2022",
        authors:["Yewande Sulaiman"], cover:pic("of-pivoting-in-the-face-of-reality-1.jpg"),
        summary:"Every time it seemed like Ope was failing to achieve his goal, he went back to the drawing board, pivoted, changed strategies and did whatever was required to succeed while staying true to his goal.",
        article:[
            "**Ross***: Pivot! Pivot!! Pivot!!!*",
            "**Chandler***: Shut up! Shut up!! Shut up!!!*",
            "You got me. I’m a huge Friends fan. Friends is that show that keeps on giving.",
            "So this article is really about **Ope Adeoye** and the evolution of [OnePipe](https://onepipe.com/) but Ross’s couch situation in [Friends](https://www.google.com/search?q=friends+pivot+episode&source=lmns&bih=730&biw=986&hl=en&sa=X&ved=2ahUKEwj4mdGb44z7AhWkTqQEHTfrAJgQ_AUoAHoECAEQAA) is such a great way to illustrate the learnings from my #founderswhodared conversation with Ope.",
            {heading:"Let’s do a quick overview", sub:true},
            "**PROBLEM – his apartment wasn’t comfortable and welcoming**",
            {points:[
                "Ross wanted a comfortable couch in his apartment (WHAT) so that kids and dates felt welcome (WHY).",
            ]},
            "**SOLUTION – the beige couch from the store down the street**",
            {points:[
                "He identified a couch he liked and from WHERE he could purchase it.",
            ]},
            "**EXECUTION – he needed to convert the idea and plan to executed outcome i.e. buying the couch and getting it into his apartment**",
            {points:[
                "He needed to transport the couch from the store to his apartment. Getting the couch from point A to point B seemed straightforward. He could ditch the delivery option seeing as it cost a lot more than he expected especially since he only lived 3 blocks away. However, he clearly didn’t think through the requirements for execution.",
            ]},
            "**FAILURE POINT 1 – carrying the couch up the stairs.**",
            {points:[
                "WHY DID THEY FAIL? They didn’t recognise the need for a different strategy to carry the couch up the flights of stairs.",
            ]},
            "**FAILURE POINT 2 – carrying the couch up the stairs with a bigger team.**",
            {points:[
                "WHY DID THEY FAIL? This time Ross tried to visualise the process, map out a plan, and brought in reinforcement (Chandler), but they were still doing the same things.",
            ]},
            {heading:"Lessons learned"},
            {ordered:true, points:[
                "Pennywise pound foolish ends up costing a lot more in the long run. They ended up breaking the couch.",
                "What got you from point A to point B will not get you from point B to point C.",
                "Got more lessons? Please share in the comments or email me @ yewande@produqtedge.com",
            ]},
            "[“Friends” The One with the Cop (TV Episode 1999) - IMDb](https://www.imdb.com/title/tt0583593/)",
            "[The One with the Cop: Directed by Andrew Tsao. With Jennifer Aniston, Courteney Cox, Lisa Kudrow, Matt LeBlanc. Joey has a dream about Monica and becomes convinced he is in love with her. Meanwhile, Phoebe finds a police badge in Central Perk, and Ross tries to get his new sofa into his apartment.](https://www.imdb.com/title/tt0583593/)",
            "[IMDb](https://www.imdb.com/title/tt0583593/)",
            "**PS: The Episode is Friends: Season 5, Episode 16 in case you’re not familiar with this story.**",
            "Ok! Back to Ope Adeoye, the father of Quickteller who is currently doing great things as the Founder and Chief Plumber of OnePipe. OnePipe is a fintech that aggregates payments services and provides them as embedded financial services across industries. They have successfully created standard APIs for tailored financial services such as payments, credit and other value-added services. OnePipe helps you launch products that have financial services layers e.g. dynamic payment gateways, credit and extended virtual accounts in days. Visit [https://onepipe.com](https://onepipe.com/) to learn more about their services.",
            "Ope started off wanting to be an engineer; you know; the kind that works in oil companies. His first career pivot happened in university when he decided to explore computers. This was a decision borne out of necessity as he felt stuck and needed something different. He pulled himself up and ventured into hardware after which he pivoted to software. In software programming, he found his love and stuck with it. The early years of his career tell a story of sheer determination and perseverance.",
            {video:"https://www.youtube-nocookie.com/embed/O9eX1Kyg3pg?rel=0&autoplay=0&showinfo=0&enablejsapi=0"},
            "Watch the #founderswhodared chat with Ope [here](https://youtu.be/O9eX1Kyg3pg) as we discuss his journey from being an engineering student, to founding his first startup shortly after uni, to joining Africa's pioneer fintech unicorn and now building OnePipe.",
            "Fast forward to 2017 when he left Interswitch to start his entrepreneurial journey. He started out with [**2iLabs**](http://2ilabs.co/), a company that positioned to incubate ideas and spin them off as projects or standalone companies. 2iLabs ran for a couple of years and a few things were apparent – he learned very quickly that it was difficult to product/project manage so many ideas at the same time. Yes, each project/idea had its own team but of course he was fully involved in all the experiments. It was his name and reputation at stake after all. Acknowledging this limitation, he took a step back with his team and chose one of the projects in their pipeline that leverages their core competencies and OnePipe was born. Since its launch, OnePipe has successfully created several partnerships with banks and other fintech providers. They continue to improve on their bouquet of services one of which is Grassroots Banking; their embedded finance offering. (I’ll be doing a deep dive on this next week. Subscribe to the newsletter so you don’t miss it).",
            {heading:"In Ope’s words; \"things need focus and commitment for them to work\"."},
            "This is absolutely true. As the saying goes – you become an expert on what you do all the time. From my experience and interactions though, there’s a FOMO that goes with focus – how do you know you’re focusing on the right thing(s)? There are so many what ifs and maybes involved. I really like [Paul Graham’s perspective](https://www.bnjs.co/transcript-paul-graham-on-focus-and-growth/) on focus though – \"*The most important thing for startups to do is to focus. Because there are so many things you could be doing, one of them is the most important. You should be doing that, and not ANY of the others.*”",
            "It’s really simple; at every time, there’s **one** most important thing for every startup. Focus on that one thing. Enter beast mode for that one thing. Give it your all and do right by it. That way, even if it fails, you can beat your chest and say you gave it your all. It's important to note however, that failure is relative. Pivoting in the face of realities such as new market information, funding realities, resource constraints is not failure; it is growth.",
            {heading:"Ope vs Ross"},
            {ordered:true, points:[
                "They both had clear goals and had ideas on how to achieve their goals.",
                "Where Ope was in tune with reality and quickly pivoted when he realised the need for change in strategy, Ross kept putting in more effort and resources using the same strategy.",
                "Ross failed and threw in the towel. Every time it seemed like Ope was failing to achieve his goal, he went back to the drawing board, pivoted, changed strategies and did whatever else was required to succeed while staying true to his goal.",
            ]},
            {heading:"My key learnings from my #founderswhodared chat with Ope Adeoye"},
            {ordered:true, points:[
                "He always had a clear goal and stayed true to it – he wanted to build a company that solved real problems. Staying true to the goal helps to clarify the journey.",
                "Identifying and deciding on the true goal helps to build focus on what truly matters – his goal was to solve problems. The problem wasn’t defined in the original goal which means the problem could change.",
                "Being clear on the mission makes it easier to define the objectives, strategies and expected outcomes.",
                "Being present and aware enough to understand and acknowledge the reality of situations – he didn’t have the resources to build a company that was incubating several ideas at the same time, so he decided to focus on one idea.",
                "Pivoting in the face of reality – he realigned his goals in uni when he came to terms with the reality of his situation – will he fail out or find alternatives? The goal here was success.",
            ]},
            "**Watch out for the next episode of #founderswhodared chat with Ope Adeoye tomorrow on our YouTube channel. It's packed! Subscribe to get notified.**",
            "[https://www.youtube.com/channel/UCUREl8_Fvp7W9uBu7GBngyQ](https://www.youtube.com/channel/UCUREl8_Fvp7W9uBu7GBngyQ)",
            "PS: Thanks to [Gloria](https://www.linkedin.com/in/gloriagowalabiri?miniProfileUrn=urn%3Ali%3Afs_miniProfile%3AACoAAAYO3EsBCpMajY7evTSs9_evAD_WK7M06CE&lipi=urn%3Ali%3Apage%3Ad_flagship3_search_srp_all%3BX8WzvMZgRNGwKPE82wtrcA%3D%3D), [Sesan](https://www.linkedin.com/in/sesan-sulaiman-71995329?miniProfileUrn=urn%3Ali%3Afs_miniProfile%3AACoAAAYDaUUBOuctiCtO8pL2Nk-GiK1YfbWvs8E&lipi=urn%3Ali%3Apage%3Ad_flagship3_search_srp_all%3B%2Bbum4UZVQ%2BGHCf9JSYF%2BkQ%3D%3D) and [Jolaade](https://www.linkedin.com/in/jolaade-sulaiman?miniProfileUrn=urn%3Ali%3Afs_miniProfile%3AACoAAAzetxQBb_Em89Oe3qF4_M8JaDyqd2F22ug&lipi=urn%3Ali%3Apage%3Ad_flagship3_search_srp_all%3Bm6lJJzBNT%2FWHIAVxjaxuFw%3D%3D) for playing Editors-in-Chief.",
        ]},
    {slug:"managing-engineering-teams-as-a-non-technical-founder-pm", title:"Managing engineering teams as a non-technical founder/PM",
        topic:"Industry Trends and Analysis", type:"Article", date:"Oct 13, 2022",
        authors:["Yewande Sulaiman"], cover:pic("managing-engineering-teams-as-a-non-technical-founder-pm-1.jpg"),
        summary:"A common question with PMs is if they need a coding background to be successful. As a non-tech PM/founder myself, I’ve learned some ways to ensure successful product delivery as a non-technical lead.",
        article:[
            "One of the most popular questions new PMs ask is if they need to have engineering knowledge to be successful. The consensus tends towards development experience not being necessary but a nice to have.",
            "You’re typically PM-ing in two main scenarios; first is you work in a mid-large organisation with some structure, and second is you’re a PM or founder working in a startup.",
            "In a startup environment, you’re typically running lean as compared with more structured environments where you have full teams with engineering leads.",
            {heading:"Beyond having a smaller team as a startup, you’re probably also dealing with one or both of these issues –", sub:true},
            {points:[
                "If you’re bootstrapping, you probably can’t afford the same level of engineers (experience and exposure) that you had the opportunity of working with at your old mid-large organisations.",
                "You no longer have the benefit of a proper structure so no escalations etc. you’re the final bus stop and you have to figure out a way to get people to commit.",
            ]},
            "**Being a non-technical PM and founder myself, and coming from more structured environments, I’ve learned some ways to ensure successful product delivery as a non-technical lead.**",
            "First off, I needed to come to terms with my reality shift. I was now in an environment where the entire buck stopped with me. Yes, being a PM had always meant I was responsible and accountable for my products but the difference between a lean startup environment and more structured organisations is that in structured environments, you have an engineering lead, a CIO or CTO or some combination of these, jobs and goals defined and segmented, and even in the flattest of structures, there was usually hierarchy of some kind.",
            "Here however, it was me and my ears. So yes, I quickly learned to acclimatise.",
            {image:pic("managing-engineering-teams-as-a-non-technical-founder-pm-2.jpg"), caption:"Managing engineering teams as a non-technical founder/PM"},
            {heading:"I identified the main issues I was facing, and after sampling the opinions of other founders, it was clear we had common pain points.", sub:true},
            {ordered:true, points:[
                "Understanding and agreeing on deliverables and timelines – you want to find the balance between getting the job done asap and being reasonable in terms of timelines but because you’re technically the CIO (not CTO) in this case, you can only estimate work with timelines your team agrees to. It puts you at the *mercy* of the team.",
                "Managing remote teams – short of installing monitoring tools on their work tools, it’s tough to ensure you have their FULL commitment within the agreed work hours.",
                "Responsibility and Ownership – Lately, a lot of people (not just engineers) have become all about the NOW. They’re interested in accumulating as much wealth (well, cash) as possible and do not mind being mediocre at 2/3 jobs rather than being great at one. I guess we have the economy to blame for this or the fact that people are just greedy and unethical.",
                "Confidence and Belief in you and your startup – I’ve also realised that one of the main reasons people take on multiple jobs is because they’re worried your startup will pack up and they’ll be left stranded. This is a fair concern to be honest so it’s important to have clear and transparent conversations with people you’re engaging so they see the big picture and understand the journey.",
                "General ‘wickedness’ – I quickly realised the truth in the Yoruba adage “gbogbo alangba lo danu dele, a o mo eyi ti inu n run”. This loosely translates to “all lizards lay flat, we can’t know the ones with tummy aches”. Some people are just wicked and there’s not much that can be done to change that. This is how I categorise issues like IP theft and other forms of scamming or shafting.",
            ]},
            {heading:"With years of iteration and practice, I've found some mitigating methods that have proven helpful in securing better outcomes for teams with these dynamics", sub:true},
            {image:pic("managing-engineering-teams-as-a-non-technical-founder-pm-3.jpg"), caption:"image 1: Example of RACI Matrix https://www.forbes.com/advisor/business/raci-chart/"},
            {ordered:true, points:[
                "**Ensuring goals and tasks are clearly defined.** Leave no room for assumptions. I know it seems like this goes without saying, but you’ll be surprised how much room we leave for assumptions especially with the definition of done.",
                "**Clearly defined roles.** No matter how lean your team is, you should have clear roles and responsibilities. Take advantage of the RACI matrix. You may have situations where the same person is responsible for multiple tasks or roles, but this should be defined. PS: This is not to be confused with clearly defined tasks. *See image 1*",
                "Inspiring confidence and belief in the project/startup by **extending ownership**. Share a bit of the pie. People want to feel like they’re a part of something great and that their contributions are valued.",
                "**Process. Process. Process.** Have clearly defined processes and stick with them. Of course, change your approach or tools if they’re not yielding the desired results but there should always be a guide to achieving the goal and it should always be adopted across the team.",
                "**Communication, transparency and respect.** This sounds mundane but it isn’t. A lot of teams have broken down due to inadequate communication. This also ties back to ownership. Transparency allows everyone to be on the same page and you can avoid ambiguity.",
                "**Governance**. Whether your startup is one day old or ten years old, governance is key. I’m not talking about corporate governance now. The governance we need here however is more focused on technology. You should have oversight of all technology access and tools. Redundancy is also very important. For instance, your code repository should be backed up regularly, you should have some level of redundancy for all your tools and access points. Your admin roles should be locked to trusted leads or only you etc.",
                "**Self-development.** Yes. You’re non-tech but working with techies means you need to level up. I don’t mean you should go and enroll in a Java for Beginners course, but you should understand the basics. Do the research. Once you’ve defined the goals of your startup/project, find out what is required to go from idea to execution and beyond. Talk to people who’ve done it before. Build a network of people who understand what you’re trying to do and engage with them.",
                "**Get yourself a technical guardian angel.** If you’ve been in the industry for a while, you probably know a few tech people you can trust. They may not be available to work on your project/startup, but they can provide guidance and help you navigate murky waters.",
            ]},
            "Good luck!",
        ]},
    {slug:"how-to-avoid-a-ten-million-dollar-mistake-most-entrepreneurs-make-right-out-the-door", title:"How to avoid a ten-million-dollar mistake most entrepreneurs make right out the door",
        topic:"Industry Trends and Analysis", type:"Article", date:"Sep 22, 2022",
        authors:["Yewande Sulaiman"], cover:pic("how-to-avoid-a-ten-million-dollar-mistake-most-entrepreneurs-make-right-out-the-door-1.jpg"),
        summary:"It's easy to get carried away when scoping a product. You're thinking of all the possibilities and sometimes get stuck midway. Adopting agile approaches solve process issues but not soft issues like product owners’ ability to detach. AFEX's product jour",
        article:[
            "Setting out to execute a startup idea is extremely exciting. You get this rush of adrenaline that makes you believe you can do just about anything. The science of creation is rather interesting – I saw a comment Blake Lively made recently about being pregnant with her 4th child - [*\"I just like to create. Whether that's baking or storytelling or businesses or humans, I just really like creating.\"*](https://www.eonline.com/amp/news/1346573/pregnant-blake-lively-speaks-out-about-baby-no.-4) She most likely meant this to be cute and funny, but the comment holds a lot of truth. We **are** designed to create; establish dominion over the earth you know.",
            "PS: click [here](https://en.wikipedia.org/wiki/Blake_Lively) if you don’t know Blake Lively.",
            "I recently had a conversation with Ayodeji Balogun; CEO of AFEX Commodities Exchange Limited (AFEX); for Founders who Dared. AFEX has been running for 10 years and it was interesting to hear about the details of their product development journey.",
            "Watch the first part of our conversation which discusses their journey to product market fit here: [https://youtu.be/guetfCrteJk](https://youtu.be/guetfCrteJk)",
            {heading:"The excitement of creation (let’s call it creator jitters) tends to lead to some or all of these –", sub:true},
            {points:[
                "oversimplify issues (in defining the problem and solution),",
                "underestimate the required inputs (cash and other resources),",
                "overestimate the required resources (technology, people, time),",
                "overestimate our abilities.",
            ]},
            "In the case of AFEX, theirs was a mistake that cost 10 million dollars, a lot of time and effort. Having clearly defined their vision and business model, execution was next. They went about creating value by connecting with their target customers, understanding their needs and defining processes to solve the identified problems. I discuss AFEX’s journey to product-market fit in the article ‘[Not your typical founder](/insights/not-your-typical-startup-founder)”.",
            {heading:"They had defined processes that worked, but then they needed to optimise for a bigger customer base…", sub:true},
            "AFEX’s key value proposition is facilitating agricultural trade in Africa. Their goals were clear; they wanted to build an exchange that allowed small-holder farmers trade their products. To this end, they needed to provide the farmers with 2 core things – access to buyers (markets), cash (loans). The manual processes they had built worked just fine. They had operators in their warehouses across multiple locations who bought inventory from farmers, paid them and sent the transaction information to their central back office in Abuja. The problem with this is – emails, uploading physical receipts and excel sheets work fine when you’re dealing with a few thousand customers; but at the point of scaling your operations, these easily become a nightmare.",
            {heading:"They set out to automate…", sub:true},
            "According to Ayodeji, their first attempt at acquiring technology went south very quickly. In typical creator jitters fashion, they over-scoped based on several assumptions that didn’t pan out. Two most significant for me were –",
            {ordered:true, points:[
                "That they hadn’t considered the maintenance requirements of the system  they were considering. Buying a world class trading platform as a startup was a clear case of overestimating the required resources. This would have had a huge toll on any startup, even if they had a large pool of funds.",
                "That they hadn’t considered the peculiarities of their markets. Their immediate markets at the time were Rwanda and Nigeria. Even with the technology advancements in Africa, we are still largely behind on infrastructure. Beyond the cost of deploying and maintaining the platform which could have sunk their ship, there was the issue of usability and customer adoption.",
            ]},
            {heading:"Getting back on the horse…", sub:true},
            "The key to success, they say, is to keep going; Consistency + Adaptation = Growth.",
            "So, they tried again. This time, they started small; with key requirements they absolutely needed to run their day-to-day operations. After several iterations, AFEX has successfully built a product that currently processes all their transactions (B2B and B2C) which amount to over ₦150bn (YTD 2022) according to the CEO.",
            "Evolving from a simple tool that consisted of a basic frontend to collect transaction data and a database to store and manage this data to a multifunctional and multi-user product is no easy feat. Kudos to the team!",
            "I had an in-depth conversation with Ayodeji on their journey from their first proprietary product; Workbench, to ComX; their holistic, customer facing product, which currently handles all trading and financing processes for the company.",
            {video:"https://www.youtube-nocookie.com/embed/F-nWgnBlM94?rel=0&autoplay=0&showinfo=0&enablejsapi=0", caption:"#FWD Interview with Ayodeji on AFEX's Product Development Journey"},
            {heading:"My key learnings from this conversation...", sub:true},
            {ordered:true, points:[
                "Scoping is not an exact science but with agile development frameworks and microservices, winning is easy(ier).",
                "Don’t spend all your money at once. You may not get more.",
                "Solve your immediate problems first.",
                "Trade-offs and prioritisation are key aspects of product management.",
                "Everyone makes mistakes. It’s important to not dwell on what’s gone wrong. Review and evaluate. Answer the questions – what you did well, what you didn’t do well, and how you can do better. Get back on the horse and give it another go.",
            ]},
            "Thank you for reading.",
            "Watch my full conversation with Ayodeji here on #FoundersWhoDared channel: [https://www.youtube.com/channel/UCUREl8_Fvp7W9uBu7GBngyQ](https://www.youtube.com/channel/UCUREl8_Fvp7W9uBu7GBngyQ)",
        ]},
    {slug:"not-your-typical-startup-founder", title:"Not your typical startup founder",
        topic:"Growth", type:"Video", date:"Sep 14, 2022",
        authors:["Yewande Sulaiman"], cover:pic("not-your-typical-startup-founder-1.jpg"),
        summary:"Founders create something out of nothing, but this description doesn’t cater for CEOs, or other people who have built businesses from scratch. An example is Ayodeji Balogun; CEO of AFEX; who I interviewed recently for Founders who Dared.",
        article:[
            "Being a 90s kid, the first thing that comes to my mind when I hear the word ‘founder’ is Shina Peters: a popular afrojuju musician (and my personal fave) who aptly described a founder as a creator, oludasile in Yoruba. Founders create something out of nothing, so it makes sense that the titles Founder and Cofounder are revered in the startup world.",
            "This description however doesn’t cater for CEOs, Directors or other titles assigned to people who have built businesses from scratch. After all, the success of startups *is* in their execution and not conceptualisation.",
            "A great example is Ayodeji Balogun; CEO of AFEX Commodities Exchange Limited (AFEX); who I interviewed recently for Founders who Dared.",
            "My conversation with Ayodeji started with a brief background into his entrepreneurial journey which interestingly started from a rather young age. Being born into a family business that dealt in the distribution of commodities across southern Nigeria, he was exposed to the intricacies of running a million-dollar enterprise. Before 25, he had closed large ticket transactions with top FMCG brands including Dangote, P&G and Sumal Foods, structured credits, raised capital and was growing their family-owned business to become one of the top distributors in the south.",
            {heading:"The WHAT was clear, so was the WHO, if only they could figure out the how", sub:true},
            "AFEX set out to simplify commodities trading across the continent, solve small holder farmer problems including access to credit, storage and markets, improve food security; thereby solving for UN SDGs including Poverty and Zero Hunger among others.",
            "Even though the company was clear on the value they wanted to deliver, the path to solving this problem was not clear. Following elaborate market analysis evaluation across African countries and with a seven-year runway in which the company was expected to have delivered on its promise and achieved profitability, they set out to testing the waters.",
            {heading:"They needed to figure out HOW to deliver the value in a repeatable and scalable way", sub:true},
            "The first thing that struck me was that they weren’t focused on building technology systems right away. Understanding peculiarities of their target market on the farmer spectrum (majority of whom are uneducated), their approach to sensitization had to be creative with clear value propositions before introducing any complexities into their operation. According to Ayodeji, the first time they knew they had found their sweet spot was when they were able to structure a transaction based on the forward value of the commodities– facilitating trade between several smallholder farmers and industry buyers.",
            {video:"https://www.youtube-nocookie.com/embed/rHRpFOq4Qrc?rel=0&autoplay=0&showinfo=0&enablejsapi=0"},
            {heading:"Defining the HOW", sub:true},
            "The team employed methods such as engaging local community heads, facilitating proof of concept transactions that were fully simplified for the farmers despite the complicated operations involved. For example, one of the first ways the company was able to drive adoption was to create simple barter-type transactions where the farmers traded produce for fertiliser. The value to the farmers was clear and simple – they needed fertiliser to prepare for their next season, they also needed to offload their harvest. They also provided storage facilities with their digitised warehouse solution.",
            "As simplistic as these offerings seemed on the farmer end, they involved complex operational processes including data collection and analysis, bulk negotiations across multiple players, and financing.",
            "The takeaway from this is clear – in providing a service or solving a problem, the target market needs to be able to directly relate to the value they will derive from adopting your solution. To the farmers, AFEX was solving their existential problems with ease.",
            {heading:"Route to scalability", sub:true},
            "As a marketplace that facilitates transactions between multiple entities, you are faced with the catch 22 question – what comes first? The chicken or the egg? Their approach to solving this problem was to simplify the more complicated part of the value chain – aggregating the commodities. In their case, getting buyers was a function of establishing and leveraging direct sales relationships (B2B).",
            "With some marketplaces, the reverse is the case. What is clear however is – understanding of your target market is the key to answering the question of the chicken or the egg.",
            "Once they were able to unlock their value delivery process, their next steps were clear. They needed to leverage technology to automate their process, improve their time to market, unlock the next level of their operation and scale. My next post discusses how they went about conceptualising their first technology products, how they stumbled and eventually found working solutions.",
            "**Watch Ayodeji’s FWD interview for the full gist**",
            {video:"https://www.youtube-nocookie.com/embed/guetfCrteJk?rel=0&autoplay=0&showinfo=0&enablejsapi=0", caption:"**Digitising Agricultural Trade in Africa (part 1)- Ayodeji Balogun(CEO AFEX)**"},
            "**Note:** FWD interviews are typically broken into episodes so we can address key issues without boring you 😁.",
        ]},
    {slug:"10-questions-to-ask-before-process-optimisation", title:"10 Questions to ask before Process Optimisation",
        topic:"Industry Trends and Analysis", type:"Article", date:"Apr 19, 2021",
        authors:["Yewande Sulaiman"], cover:pic("10-questions-to-ask-before-process-optimisation-1.jpg"),
        summary:"Growth is what we all aspire to. But growth in organisations inevitably lead to obsolete processes. Asking these 10 question to ask when embarking on a process improvement initiative will help you ensure your desired outcome and a smooth path from AS IS t",
        article:[
            "Every organisation has multiple processes that come together to generate successful outcomes. These processes are typically designed at different stages in the organisation’s lifecycle. Over time they get outdated as realities change – market changes, technology advances, changes in resources – are a few things that can contribute to this.",
            "It’s important to review operational processes regularly. This helps to identify inefficiencies in these processes and find the best ways to improve them. In most cases, the first solution that comes to mind is automation; and even when the process is already automated, we try to find ways to either increase our processing speed either increasing infrastructure or running some steps concurrently or some other quick fix.",
            "These quick fixes most of the time end up either creating more problems or not fixing the identified ones; and what’s more – they’re not usually cost effective. I bet you’re thinking okay, what then?",
            "Process improvement / optimisation in itself is a process and it pays to follow identified best practice. It’s important to ask pertinent questions; the most important of which is – What problem are we trying to solve and what does a successful outcome represent?",
            "Breaking this down and asking other key questions will help you achieve the desired outcome –",
            {points:[
                "What is this problem we’re trying to fix?",
                "Is it local or general?",
                "What does a successful upgrade look like?",
                "How do we measure the success? Reduced TAT? Less resources?",
                "Will automation solve it?",
                "Do you really need to automate?",
                "How much would the automation cost?",
                "What happens if you don’t automate?",
                "What’s the benefit-cost ratio (BCR)?",
                "Are there other ways to fix it?",
            ]},
            "To effectively answer these questions, you’ll need to have a true picture of the current situation (AS IS). Process mapping are very effective tools for this. The next step would be to evaluate the process in detail by conducting a Root Cause Analysis (RCA).",
            "Doing this helps to narrow down which part of your process is actually causing the inefficiencies and what exactly needs to be changed. The problem could be with the flow sequence, or a particular step that takes longer or requires more hands, or a number of other issues that will become very apparent. Once the root cause is identified, solving the problem becomes a walk in the park e.g. you may only need to improve one part of the process or change the flow. This process may sound painstaking, but the cost-benefit is definitely worth it.",
            "Below is a suggested roadmap to making the journey from AS IS to TO BE easier. We’ve also included a few very helpful tools to help you on this journey.",
            {image:pic("10-questions-to-ask-before-process-optimisation-2.jpg"), alt:"A picture containing scissorsDescription automatically generated"},
            "ProduqtEdge partners with companies to create more optimised versions of themselves. We are interested in helping you achieve your goals. Reach out today to claim your free first consultation.",
            "[Get your FREE Review](/)",
        ]},
    {slug:"seriously-why-do-projects-still-fail", title:"Seriously, why do projects still fail?",
        topic:"Industry Trends and Analysis", type:"Article", date:"Mar 14, 2020",
        authors:["Yewande Sulaiman"], cover:pic("seriously-why-do-projects-still-fail-1.jpg"),
        summary:"Even with several agile methodologies and frameworks designed to build successful products, failure rates are still quite high. Whether in startups or BigCos So why do projects fail? Some reasons that jump out at me include - definition of done, scope cre",
        article:[
            "If you've spent any time in project or product management, you're most likely familiar with this customer requirement image..",
            "Generally, we could define a successful project/product as one that is delivered on time, within budget and cost and delivers value in line with stakeholders’ requirements. However, as have been identified by several studies, we still have a high level of project failures; even with agile methodologies.",
            "I’ve curated a few reasons that jump out to me below. These are majorly from my experience and in my opinion (though quite a few have been identified by bodies including PMI and The Standish Group)",
            "1. Sentimental attachments lead to sometimes cloudy judgment. When you are super close to the product, you are sentimentally attached; you most likely will make sentimental decisions as against data driven ones. It’s like having and raising a baby… you just can’t separate yourself from some things. Well, unless you‘re like my mother shaa.. that woman will beat you like she didn’t carry you for 9 months then walk up and down Oluyoro in the middle of the night to induce labour..",
            "2. Managing stakeholder requirements (i.e. gathering, interpreting and communicating) is one of the most important steps to ensuring the right solution is developed. As depicted in the image above, the client’s request usually ends up different from what gets built. So you find that earlier in planning and development, ideas are usually vague, then as development progresses and the product begins to take shape, stakeholders tend to be more articulate in stating their requirements more specifically. Why? Well, now they have a point of reference basically. I know you’re thinking err… what happened to mockups and prototypes? Yes. They do help to create a less vague interpretation of the stakeholders’ requirements and the more detailed they are the better. However, unfortunately, because many times, we want to go to market NOW NOW, we skip a few steps and as expected, they come back to bite us in the behind.",
            "3. Scope creep is the devil. As the product becomes clearer during development, ideas and/or market realities evolve which means that the team needs to reevaluate initial requirements and incorporate changes. Sometimes this means an entire change to the drawing board which naturally means more time and resources. In a waterfall environment, major changes such as these would most of the time lead to the death of the project. With Agile environments, failing fast and failing forward is the mantra.",
            "4. Definition of Done. Ideally, the definition of done (when a backlog item is done) should be agreed upon before development; but somehow, you find that the goal post keeps moving. Moving goal posts are typically as a result of increasing clarity of how we want to deliver value as the product unfolds. This as well can be solved by setting clear goals during design and planning. No matter how small the increment is, breaking it down into clear achievable parts, with visual representation where required helps remove ambiguity.",
            "5. Relegating requirements management to just a project document. So it’s one thing to gather requirements and document them; it’s another thing to actually have a process in place to manage them. Having a defined process helps the team to be ready for changes and adapt to them properly. Processes can also be adapted to fit current realities; however, we should have a baseline – always.",
            "6. You cannot not involve stakeholders enough. Lol… that sentence is so weird, but seriously, ensuring that all key stakeholders are carried along at every step of the way saves a lot of time spent on rework. Product Owner wants to make sure that the goal is clear. You want to repeat your understanding of the product/project objective, features and roadmap, sprint goal, delivery targets and everything in between because in the long run, after all your late nights and early mornings, if your stakeholders are not happy with the output… oh well..",
            "Ok.. so basically, what I’ve found is – clear definitions of goals, processes and acceptance criteria are key to achieving success and clearly understood and effectively managed requirements are the oil that greases the wheels helping to avoid design rework and reducing development failures. Here’s a [link](https://community.plm.automation.siemens.com/t5/Solid-Edge-Blog/Why-Requirements-Management-Matters-in-Product-Development/ba-p/514210) to an article about requirements management that I find very interesting.",
        ]},
    {slug:"breaking-into-new-markets-what-are-you-overlooking", title:"Breaking into new markets… what are you overlooking?",
        topic:"Product Management", type:"Article", date:"Aug 13, 2019",
        authors:["Yewande Sulaiman"], cover:pic("breaking-into-new-markets-what-are-you-overlooking-1.jpg"),
        summary:"You’ve developed a successful product in your current market and are looking to grow your TAM. How do you ensure your product fits your new markets?",
        article:[
            "Working with companies at different stages of expansion gave me some perspective on how much we seem to overlook when making growth decisions to expand market share especially by developing new markets.",
            "First, a bit of background on growth and expansion strategies. Are you familiar with the **Ansoff Matrix**? Well, without getting academic, Ansoff Matrix is a matrix that identifies four strategies of growth by evaluating the relationship between products, addressable markets and the associated risks of developing either. It’s also called the **Product/Market Grid**.",
            {image:pic("breaking-into-new-markets-what-are-you-overlooking-2.jpg"), caption:"Ansoff Matrix"},
            "The four strategies are –",
            "· Market Penetration – which is where the company focuses on selling existing products to existing customers.",
            "· Market development – this involves selling existing products to new customers.",
            "· Product development – here we develop new products for existing customers.",
            "· Diversification – involves developing new products for new markets.",
            "Please see [**here**](https://en.wikipedia.org/wiki/Ansoff_Matrix) for more information on the Ansoff Matrix and other related tools.",
            "Now back to growth strategies. You’ll agree that increasing adoption and obtaining significant market share is the recipe for organic growth. The question is – how do you do it right?",
            "There are a lot of key factors that companies should consider when venturing into new markets regardless of what stage of growth they’re at – I’ll jump right in.",
            "**1. Product-Market Fit**",
            "It’s all well and good that you’ve developed a successful product in your current market and are looking to grow your addressable market by targeting new customers (usually in new regions). You should ask however – does the new market you’ve identified have the same problem your product solves in your existing one? Is your product able to solve a specific problem or satisfy a need in the new market? Is that market ready for the solution? Yes, I know, that popular saying – If Henry Ford had asked his customers what they wanted, they would’ve said a faster horse. Agreed. Customers don’t always know what they want (or at least can’t always articulate their needs) but with proper research, you can find out if your customers actually have a need or problem to be solved. In Henry Ford’s case, people needed a faster means of transportation – shikena!",
            "**2. Cultural diversity**",
            "Breaking into new markets means you engaging a new kind of people – new clients, partners, employees, regulators and competitors. The difference in cultures can make or break your expansion or diversification efforts. Interestingly, cultures can be very distinct even across the same geographical regions. Example, some countries in Africa have labour laws that allow employees take 2-hour lunch breaks; and they take them very seriously! To a Nigerian (who is used to working from 7am till midnight), this would be rather strange; but if you’ve done your due diligence about your proposed new markets, you would have made provision for these requirements beforehand.",
            "**3. Regulatory requirements**",
            "This is especially important for financial service providers amongst others. Every region has rules that govern them and being familiar with these should be at the top of your checklist. Regulatory limitations may be show stoppers for your product there’s no point in investing time and resources only to find that you can’t operate in that market. For instance, if your USP is instant value to merchants and the region has a rule against that; your product is DOA.",
            "It helps to engage local SMEs and look up relevant policies (usually published on regulators’ websites).",
            "**4. Local Infrastructure**",
            "This speaks for itself. A typical example is Africa; the new hotspot for tech startups and diversification in general. Bringing in a payment product will require you to evaluate the existing infrastructure your product needs to leverage on i.e. what switches are on ground? Will you need to leverage the incumbents? What level of integration will be required? Will they be open to partnering with you? Will you build from scratch? What kind of investment will that require – time, money, people?",
            "PS: You would notice my examples default to payment industry. Familiarity, I guess.",
            "**5. Costs**",
            "I’m not talking about high level costs now. I mean real costs. When divesting to some developing countries like Nigeria for example, you have to consider costs at the most minuscule level – e.g. the cost of generating your own electricity, the cost of having additional physical security, the cost of transportation, the cost of finding skilled employees (what with a lot of our good hands shipping west), cost of living and lots more.",
            "**6. Local competition**",
            "I don’t think it’s possible to stress enough how important it is to understand the local competition. What do they do? How do they do it? How do they retain their customers? How will you convert their customers? What will you do differently? How will you make your product sticky?",
            "Porter’s 5 Forces, Competitor Analysis Model and SWOT Analysis are great tools that can help here.",
            "**7. Your own company structure and culture**",
            "Due to cultural and environmental differences, you may not be able to run the same structures and practices as in your previous markets. For instance, if you typically run a remote shop, you may need to evaluate the productivity level of your new employees if you find yourself in markets where (for instance) people are not exactly self-starters or don’t have access to constant electricity or internet.",
            "**8. Pricing**",
            "Pricing is another very key factor. If your product is priced higher than the purchasing power of your target customer in the new market, it’s DOA. It’s important to evaluate your costs of production (taking into consideration all the peculiarities of the new market) vs selling price and your target customers’ purchasing power before making any solid plans or investments. Well, unless you’re running a charity.",
            "**9. Scalability**",
            "Remember to do your detailed forecasts whether you have a board of investors chasing you or not. It’s important to chart the course at least a few years ahead (typically 4 or 5) with educated assumptions and make informed decisions as to the viability of your plans.",
            "**10. Local network**",
            "It helps to have a local network – partners, brokers, investors, industry experts etc – that have domain knowledge and are able and willing to share critical information (ethically!), broker relationships and deals and generally give you a soft landing. And beware of fraudulent people… I know it sounds redundant but err…",
            "**11. Other things to consider include**",
            "- Availability of local skill",
            "- Your company’s bandwidth",
            "- Organic growth vs partnerships and/or acquisitions",
            "Generally, due diligence is very important in any venture; no matter how small. Better to be sceptical and wrong than to be overly optimistic and fall flat on your face. Of course, there would always be the element of surprise but at least you would have covered most of your bases.",
            "Thanks for taking the time to read this. This is an interesting area for me and I’m available to discuss anytime. Shoot me an email at [yewande@produqtedge.com](mailto:yewande@produqtedge.com) with questions, comments or requests for templates of tools I mentioned.",
        ]},
    {slug:"digital-transformation---from-complex-silos-to-future-ready", title:"Digital transformation – From Complex Silos to Future Ready…",
        topic:"Industry Trends and Analysis", type:"Article", date:"Jul 14, 2019",
        authors:["Yewande Sulaiman"], cover:pic("digital-transformation---from-complex-silos-to-future-ready-1.jpg"),
        summary:"To become Future Ready, a company must transform across three dimensions: customer experience, operational efficiency and organisational culture.",
        article:[
            "A lot of organizations are either on a journey towards digital transformation or trying to figure out what the heck it is and how to approach it. This process can get convoluted and confusing. Most organisations just end up benchmarking against an industry leader. The problem with this is organisational change is peculiar; even within the same industries and markets, no two organisations are the same and implementing a one-size-fits-all approach isn’t always effective. Someone else’s best practice is not necessarily your best practice.",
            "So how does one go from point X to the promised land – i.e. **Future Ready** state where you’re innovating with a customer centric mindset while maintaining low costs; leveraging readily available technologies as defined by MIT CISR.",
            "To become Future Ready, a company must transform across three dimensions: **customer experience**, **operational efficiency** and **organisational culture**. These embody aspects of the organisation including organisational structure, infrastructure, process, product, brand, core values, employees’ thinking, people management, knowledge management and more.",
            "Before focusing on these aspects of change however, the first and most important step is identifying what exactly needs to change. This process of identifying where you currently are (**AS IS**) and where you’d like to be (**TO BE**) – **Discovery** or **Gap Analysis**, is the key to a successful transformation.",
            "To put some perspective, imagine building a 20-storey building on a foundation that was designed for a bungalow! This can only occur where preliminary findings such as soil testing, confirmation of client requirements and budget, modelling etc were skipped or improperly done before plunging into building. The Discovery process is equivalent to these preliminary steps in building a house. Now we can proceed to figuring out which path will lead the company to salvation and how to prioritise the changes.",
            "At ProduqtEdge, we are a team of experienced consultants with broad industry knowledge and technology experience, whose primary focus is to help and guide organisations through their transformation journeys. We work with you to find the most optimal ways to improve your organisation in line with your long-term and short-term strategies.",
            "Our services include-",
            {points:[
                "Startup Incubation",
                "Product Management Trainings",
                "Product Management Consulting (includes Governance and Team Building)",
                "Project Management and Execution",
                "Process Audit and Optimisation",
            ]},
        ]},
]
